/**
 * Shared GLSL functions for the Original Buddies Blitz Flat Ground Map (elevation = 0, curvature = 0):
 * - evaluateBlitzGrassMask(vec2 p): soft organic splatmap mask between warm sandy-brown dirt (#d6a868)
 *   and lush green grass (#4ea832 -> #9be15d), matching buddiesPlanetCurvature.ts 1:1 on CPU and GPU.
 * - getRawGroundElevation(vec2 p): 0.0 inside playable arena + two-tier Outer Perimeter Hill Embankment ("Tanggul Bukit").
 */
const PLANET_TERRAIN_GLSL_SNIPPET = /* glsl */ `
  uniform sampler2D uSculptMap;

  vec2 wrapPlanetVec2(vec2 p) {
    return clamp(p, vec2(-130.0), vec2(130.0));
  }

  float samplePlanetMultiOctaveNoise(vec2 p) {
    float k1 = 0.07853981633974483;
    float k2 = 0.15707963267948966;
    float k3 = 0.3141592653589793;

    float octave1 = sin(p.x * k1 + cos(p.y * k1) * 1.15) * cos(p.y * k1 - sin(p.x * k1) * 0.95);
    float octave2 = sin(p.x * k2 - p.y * k1 * 1.5 + 1.3) * 0.55 + cos(p.y * k2 + p.x * k1 - 0.8) * 0.45;
    float octave3 = sin(p.x * k3 + p.y * k2) * cos(p.y * k3 - p.x * k2);

    return octave1 * 0.58 + octave2 * 0.28 + octave3 * 0.14;
  }

  float sdSegment2D(vec2 p, vec2 a, vec2 b) {
    vec2 pa = p - a;
    vec2 ba = b - a;
    float h = clamp(dot(pa, ba) / (dot(ba, ba) + 1e-6), 0.0, 1.0);
    return length(pa - ba * h);
  }

  float sdRoundedBox2D(vec2 p, vec2 c, vec2 h, float r) {
    vec2 q = abs(p - c) - h + r;
    return length(max(q, 0.0)) + min(max(q.x, q.y), 0.0) - r;
  }

  float blitzSmin(float a, float b, float k) {
    float h = max(k - abs(a - b), 0.0) / k;
    return min(a, b) - h * h * k * 0.25;
  }

  float evaluateWestPowerPlantSdf(vec2 p) {
    return sdRoundedBox2D(p, vec2(-90.5, 0.0), vec2(14.0, 38.0), 2.4);
  }

  float evaluateEastConstructionYardSdf(vec2 p) {
    return sdRoundedBox2D(vec2(p.x, abs(p.y)), vec2(88.5, 75.0), vec2(13.0, 29.0), 2.5);
  }

  vec4 evalEmbankmentTierOffsets(vec2 p) {
    float dBox = sdRoundedBox2D(p, vec2(48.25, 0.0), vec2(144.75, 113.5), 34.0);
    float westCornerBulge =
      smoothstep(-54.0, -90.0, p.x) * smoothstep(62.0, 102.0, abs(p.y)) * 11.5;
    float westPlantClear =
      smoothstep(-76.0, -104.0, p.x) * (1.0 - smoothstep(36.0, 44.0, abs(p.y))) * 9.5;
    float tennisClubClear =
      smoothstep(-74.0, -102.0, p.x) *
      (12.2 - 1.7 * smoothstep(-106.0, -112.0, p.x)) *
      smoothstep(35.0, 41.0, p.y) *
      (1.0 - smoothstep(75.0, 82.0, p.y));
    float eastCoastalOpen = smoothstep(96.5, 102.0, p.x) * 92.0;
    float d0 = dBox + westCornerBulge - westPlantClear - tennisClubClear - eastCoastalOpen;
    if (d0 < -6.5) {
      return vec4(d0, d0 - 6.0, d0 - 12.0, d0 - 18.0);
    }

    float w1 =
      sin(p.x * 0.075 + cos(p.y * 0.068) * 1.55) * 2.05 +
      cos(p.y * 0.072 - sin(p.x * 0.065) * 1.55) * 1.75 +
      sin((p.x - p.y) * 0.14) * 0.65;

    float nsCompact = 1.0 - 0.24 * smoothstep(92.0, 115.0, abs(p.y));
    float stepW12 =
      (5.8 +
        2.1 * sin(p.x * 0.064 - p.y * 0.070 + 1.1) +
        1.1 * cos(p.x * 0.13 + p.y * 0.11 - 0.6)) *
      nsCompact;
    float stepW23 =
      (6.2 +
        2.3 * cos(p.x * 0.058 + p.y * 0.066 - 1.9) +
        1.2 * sin(p.x * 0.12 - p.y * 0.14 + 1.4)) *
      nsCompact;
    float stepW34 =
      (6.5 +
        2.4 * sin(p.x * 0.054 + p.y * 0.060 + 2.7) +
        1.2 * cos(p.x * 0.11 + p.y * 0.13 - 2.1)) *
      nsCompact;

    float t1 = d0 + w1;
    float t2 = t1 - max(3.45, stepW12);
    float t3 = t2 - max(3.55, stepW23);
    float t4 = t3 - max(3.65, stepW34);
    return vec4(t1, t2, t3, t4);
  }

  float evaluateOuterEmbankmentSdf(vec2 p) {
    return max(evalEmbankmentTierOffsets(p).x, p.x - 109.2);
  }

  float evalMirroredCentralSCurveDist(vec2 p, float az) {
    vec2 q = vec2(p.x, az);
    float s1 = sdSegment2D(q, vec2(-70.0, 15.0), vec2(-52.0, 15.0));
    float s2 = sdSegment2D(q, vec2(-52.0, 15.0), vec2(-41.0, 26.0));
    float s3 = sdSegment2D(q, vec2(-41.0, 26.0), vec2(-25.0, 26.0));
    float s4 = sdSegment2D(q, vec2(-25.0, 26.0), vec2(-13.0, 14.0));
    float s5 = sdSegment2D(q, vec2(-13.0, 0.0), vec2(-13.0, 14.0));
    float s6 = sdSegment2D(q, vec2(-13.0, 14.0), vec2(9.0, 14.0));
    float s7 = sdSegment2D(q, vec2(9.0, 14.0), vec2(19.0, 24.0));
    float s8 = sdSegment2D(q, vec2(19.0, 24.0), vec2(42.0, 24.0));
    float s9 = sdSegment2D(q, vec2(-25.0, 26.0), vec2(-18.0, 33.0));
    float s10 = sdSegment2D(q, vec2(-18.0, 33.0), vec2(-18.0, 52.0));
    float s11 = sdSegment2D(q, vec2(19.0, 24.0), vec2(19.0, 52.0));
    float s12 = sdSegment2D(q, vec2(42.0, 24.0), vec2(52.0, 15.0));
    float s13 = sdSegment2D(q, vec2(52.0, 15.0), vec2(70.0, 15.0));
    float s14 = sdSegment2D(q, vec2(42.0, 24.0), vec2(42.0, 52.0));
    return min(
      min(min(min(s1, s2), min(s3, s4)), min(min(s5, s6), min(s7, s8))),
      min(min(min(s9, s10), min(s11, s12)), min(s13, s14))
    );
  }

  float evaluateRoadNetworkSdf(vec2 p) {
    float az = abs(p.y);
    vec2 q = vec2(p.x, az);

    float dWest = sdSegment2D(q, vec2(-70.0, 0.0), vec2(-70.0, 44.0));
    float dEast = sdSegment2D(q, vec2(70.0, 0.0), vec2(70.0, 44.0));
    float dCollector = sdSegment2D(q, vec2(-62.0, 52.0), vec2(62.0, 52.0));
    float dHarborTurn = sdSegment2D(q, vec2(70.0, 15.0), vec2(76.5, 15.0));

    float dCornerW = (p.x <= -62.0 && az >= 44.0) ? abs(length(q - vec2(-62.0, 44.0)) - 8.0) : 999.0;
    float dCornerE = (p.x >= 62.0 && az >= 44.0) ? abs(length(q - vec2(62.0, 44.0)) - 8.0) : 999.0;

    float dBaseWestOuter = sdSegment2D(q, vec2(-60.0, 52.0), vec2(-60.0, 108.0));
    float dBaseEastOuter = sdSegment2D(q, vec2(60.0, 52.0), vec2(60.0, 108.0));
    float dComplexDiv1 = sdSegment2D(q, vec2(-30.0, 52.0), vec2(-30.0, 108.0));
    float dComplexDiv2 = sdSegment2D(q, vec2(0.0, 52.0), vec2(0.0, 108.0));
    float dComplexDiv3 = sdSegment2D(q, vec2(30.0, 52.0), vec2(30.0, 108.0));
    float dBaseRear = sdSegment2D(q, vec2(-60.0, 108.0), vec2(60.0, 108.0));
    float dGateDrive1 = sdSegment2D(q, vec2(-45.0, 52.0), vec2(-45.0, 64.2));
    float dGateDrive2 = sdSegment2D(q, vec2(-15.0, 52.0), vec2(-15.0, 64.2));
    float dGateDrive3 = sdSegment2D(q, vec2(15.0, 52.0), vec2(15.0, 64.2));
    float dGateDrive4 = sdSegment2D(q, vec2(45.0, 52.0), vec2(45.0, 64.2));

    float dOuterAndBaseRing = min(
      min(
        min(min(min(dWest, dEast), dCollector), min(dHarborTurn, min(dCornerW, dCornerE))),
        min(min(dBaseWestOuter, dBaseEastOuter), min(min(dComplexDiv1, dComplexDiv2), min(dComplexDiv3, dBaseRear)))
      ) - 3.9,
      min(min(dGateDrive1, dGateDrive2), min(dGateDrive3, dGateDrive4)) - 2.6
    );

    float dCentralSCurve = evalMirroredCentralSCurveDist(p, az) - 4.2;
    return min(dOuterAndBaseRing, dCentralSCurve);
  }

  float evaluateNwLakeSdf(vec2 p) {
    vec2 q = vec2(p.x, abs(p.y));
    if (p.x < -48.0 || p.x > -14.0 || q.y > 18.5) {
      return 20.0;
    }
    float d1 = length(q - vec2(-31.0, 0.0)) - 8.4;
    float d2 = length(q - vec2(-26.5, 4.2)) - 6.8;
    float d3 = length(q - vec2(-35.0, 4.5)) - 6.8;
    float d4 = length(q - vec2(-30.5, 7.2)) - 6.2;
    float wave = sin(q.x * 0.26 + cos(q.y * 0.22)) * 0.55 + cos(q.y * 0.31 - q.x * 0.19) * 0.40;
    return blitzSmin(blitzSmin(d1, d2, 4.0), blitzSmin(d3, d4, 4.0), 4.0) + wave;
  }

  vec2 evaluateSeHarborSdf(vec2 p) {
    float dHarborDock = sdRoundedBox2D(p, vec2(93.0, 0.0), vec2(17.0, 46.0), 2.4);
    float dCoastalWall = sdRoundedBox2D(p, vec2(105.75, 0.0), vec2(4.25, 180.0), 0.8);
    float concreteSdf = min(dHarborDock, dCoastalWall);
    float waterSdf = 110.0 - p.x;
    return vec2(concreteSdf, waterSdf);
  }

  float evalModelEstateBaseDirtSdf(vec2 p) {
    float dPlot0 = sdRoundedBox2D(p, vec2(-45.0, 81.7), vec2(9.8, 17.5), 0.8);
    float dSpur0 = sdSegment2D(p, vec2(-45.0, 64.2), vec2(-45.0, 52.0)) - 2.65;
    return min(dPlot0, dSpur0);
  }

  float evalHaltePlatformSdf(vec2 p) {
    float dCentral = sdRoundedBox2D(p, vec2(-61.66, 0.0), vec2(3.6, 9.4), 0.4);
    float dNorth = sdRoundedBox2D(p, vec2(6.5, -44.67), vec2(9.4, 3.6), 0.4);
    float dSouth = sdRoundedBox2D(p, vec2(-36.5, 44.67), vec2(9.4, 3.6), 0.4);
    float dBeach = sdRoundedBox2D(p, vec2(79.63, 29.5), vec2(3.6, 9.4), 0.4);
    float dPlazaSidewalk = sdRoundedBox2D(p, vec2(-75.25, 0.0), vec2(1.45, 38.2), 0.2);
    float dTennisClub = sdRoundedBox2D(p, vec2(-89.20, 51.90), vec2(15.20, 13.70), 0.3);
    return min(dTennisClub, min(dPlazaSidewalk, min(dCentral, min(dNorth, min(dSouth, dBeach)))));
  }

  float evaluateBlitzGrassMaskFromSdfs(
    vec2 p,
    float roadSdf,
    float lakeSdf,
    vec2 harborSdf,
    float westPlantSdf,
    float embSdf
  ) {
    float pz = p.y;
    vec2 q = (pz < 0.0) ? -p : p;

    float n1 = sin(q.x * 0.17 + cos(q.y * 0.15) * 1.6) * cos(q.y * 0.16 - sin(q.x * 0.14) * 1.4);
    float n2 = sin(q.x * 0.37 - q.y * 0.31 + 0.9) * 0.5 + cos(q.y * 0.41 + q.x * 0.29 - 0.6) * 0.5;
    float wobble = (n1 * 0.65 + n2 * 0.35) * 1.05;

    float dModelEstateDirt = evalModelEstateBaseDirtSdf(p);
    float dConstructionYardDirt = evaluateEastConstructionYardSdf(p);

    float minDirtSdf = min(dModelEstateDirt, dConstructionYardDirt) + wobble;
    float grassMask = smoothstep(-0.35, 1.35, minDirtSdf);

    float roadSafe = smoothstep(-0.15, 0.85, roadSdf);
    float lakeSafe = smoothstep(0.2, 1.65, lakeSdf);
    float harborSafe = smoothstep(-0.2, 1.25, min(harborSdf.x, harborSdf.y));
    float westPlantSafe = smoothstep(-0.2, 1.15, westPlantSdf);

    float hardPadSdf = min(dModelEstateDirt, dConstructionYardDirt);
    float padSafe = smoothstep(-0.3, 0.5, hardPadSdf);
    float embSafe = 1.0 - smoothstep(-0.6, 0.8, embSdf);

    float halteSdf = evalHaltePlatformSdf(p);
    float halteSafe = smoothstep(-0.2, 0.6, halteSdf);

    return clamp(grassMask * roadSafe * lakeSafe * harborSafe * westPlantSafe * padSafe * embSafe * halteSafe, 0.0, 1.0);
  }

  float evaluateBlitzGrassMask(vec2 p) {
    return evaluateBlitzGrassMaskFromSdfs(
      p,
      evaluateRoadNetworkSdf(p),
      evaluateNwLakeSdf(p),
      evaluateSeHarborSdf(p),
      evaluateWestPowerPlantSdf(p),
      evaluateOuterEmbankmentSdf(p)
    );
  }

  float getRawGroundElevation(vec2 rawP) {
    vec2 p = wrapPlanetVec2(rawP);
    vec2 sculptUv = clamp((p + 130.0) / 260.0, 0.0, 1.0);
    float sculptOffset = (texture2D(uSculptMap, sculptUv).r * 255.0 - 128.0) * 0.0625;
    vec2 harborSdf = evaluateSeHarborSdf(p);
    float harborDrop = -1.65 * smoothstep(0.15, -0.85, harborSdf.y);

    float westPlantSdf = evaluateWestPowerPlantSdf(p);
    // Keep underlying procedural terrain mesh strictly inside the Plaza retaining walls (westPlantSdf < -0.40)
    // so CurvedPlanetGround NEVER pokes through the +0.09m Roadside Sidewalk ("di trotoar plaza masih ada tanah")
    float westPlantElev = (1.0 - smoothstep(-0.85, -0.40, westPlantSdf)) * 0.40;
    if (p.x > -85.45 && p.x < -75.40 && abs(p.y) < 10.05) {
      float stairCarveX = smoothstep(-85.45, -84.50, p.x);
      float stairCarveZ = 1.0 - smoothstep(9.60, 10.05, abs(p.y));
      westPlantElev = mix(westPlantElev, 0.0, stairCarveX * stairCarveZ);
    }

    float lakeSdf = evaluateNwLakeSdf(p);
    float lakeBasinDepression = 0.0;
    if (lakeSdf < 0.85) {
      float lakeStep1 = (1.0 - smoothstep(-0.45, 0.85, lakeSdf)) * 0.48;
      float lakeStep2 = (1.0 - smoothstep(-2.60, -1.10, lakeSdf)) * 0.52;
      float lakeStep3 = (1.0 - smoothstep(-5.60, -3.20, lakeSdf)) * 0.55;
      lakeBasinDepression = lakeStep1 + lakeStep2 + lakeStep3;
    }

    float baseArenaElev = westPlantElev - lakeBasinDepression;
    vec4 embT = evalEmbankmentTierOffsets(p);
    float embElev = 0.0;
    if (embT.x > -0.1) {
      float step1 = smoothstep(0.0, 1.45, embT.x) * 3.2;
      float step2 = smoothstep(0.0, 1.50, embT.y) * 2.9;
      float step3 = smoothstep(0.0, 1.55, embT.z) * 2.7;
      float step4 = smoothstep(0.0, 1.60, embT.w) * 2.6;
      embElev = step1 + step2 + step3 + step4;
    }
    return sculptOffset + harborDrop + max(baseArenaElev, embElev);
  }

  float planetValueNoise(vec2 p) {
    vec2 i = floor(p);
    vec2 f = fract(p);
    vec2 u = f * f * (3.0 - 2.0 * f);
    float a = fract(sin(dot(i, vec2(127.1, 311.7))) * 43758.5453123);
    float b = fract(sin(dot(i + vec2(1.0, 0.0), vec2(127.1, 311.7))) * 43758.5453123);
    float c = fract(sin(dot(i + vec2(0.0, 1.0), vec2(127.1, 311.7))) * 43758.5453123);
    float d = fract(sin(dot(i + vec2(1.0, 1.0), vec2(127.1, 311.7))) * 43758.5453123);
    return mix(mix(a, b, u.x), mix(c, d, u.x), u.y);
  }
`;

/**
 * GLSL snippet for sampling crisp real-time DirectionalLight shadows + Blitz's 45° halftone dot edge
 * on both the Flat Splatmap Ground and InfiniteGrass blades.
 */
const BLITZ_CAST_SHADOW_GLSL_SNIPPET = /* glsl */ `
  uniform sampler2D uDirShadowMap;
  uniform mat4 uDirShadowMatrix;
  uniform float uHasDirShadow;

  float blitzHalftoneGrid(vec2 coord, float scale) {
    float c = 0.70710678;
    float s = 0.70710678;
    vec2 rot = vec2(coord.x * c - coord.y * s, coord.x * s + coord.y * c) * scale;
    float dist = length(fract(rot) - 0.5);
    return smoothstep(0.24, 0.42, dist);
  }

  float sampleBlitzCastShadow(vec3 worldPos) {
    if (uHasDirShadow < 0.5) return 1.0;
    vec4 shadowCoord = uDirShadowMatrix * vec4(worldPos, 1.0);
    shadowCoord.xyz /= shadowCoord.w;
    if (
      shadowCoord.x <= 0.002 ||
      shadowCoord.x >= 0.998 ||
      shadowCoord.y <= 0.002 ||
      shadowCoord.y >= 0.998 ||
      shadowCoord.z >= 1.0 ||
      shadowCoord.z <= 0.0
    ) {
      return 1.0;
    }
    float zRef = shadowCoord.z - 0.0012;
    vec2 texel = vec2(1.0 / 1024.0);
    float s0 = step(zRef, texture2D(uDirShadowMap, shadowCoord.xy).r);
    float s1 = step(zRef, texture2D(uDirShadowMap, shadowCoord.xy + vec2(texel.x, texel.y) * 0.75).r);
    float s2 = step(zRef, texture2D(uDirShadowMap, shadowCoord.xy + vec2(-texel.x, -texel.y) * 0.75).r);
    float s3 = step(zRef, texture2D(uDirShadowMap, shadowCoord.xy + vec2(texel.x, -texel.y) * 0.75).r);
    float s4 = step(zRef, texture2D(uDirShadowMap, shadowCoord.xy + vec2(-texel.x, texel.y) * 0.75).r);
    return (s0 * 2.0 + s1 + s2 + s3 + s4) / 6.0;
  }
`;

export interface BlitzWindUniforms {
  uTime: { value: number };
  uWindPhase: { value: number };
  uWindDirection: { value: THREE.Vector2 };
  uWindStrength: { value: number };
  uWindGust: { value: number };
  uLightDirection: { value: THREE.Vector3 };
  uLightColor: { value: THREE.Color };
  uShadowColor: { value: THREE.Color };
  uPlanetPivot?: { value: THREE.Vector3 };
  uCurvatureStrength?: { value: number };
  uSculptMap?: { value: THREE.DataTexture };
  uDirShadowMap?: { value: THREE.Texture | null };
  uDirShadowMatrix?: { value: THREE.Matrix4 };
  uHasDirShadow?: { value: number };
}

let sharedSculptDataTexture: THREE.DataTexture | null = null;
let lastSyncedSculptVersion = -1;

export function getOrCreateSharedSculptTexture(): THREE.DataTexture {
  if (!sharedSculptDataTexture) {
    sharedSculptDataTexture = new THREE.DataTexture(
      terrainSculptRgbaData,
      SCULPT_GRID_SIZE,
      SCULPT_GRID_SIZE,
      THREE.RGBAFormat,
      THREE.UnsignedByteType,
    );
    sharedSculptDataTexture.wrapS = THREE.RepeatWrapping;
    sharedSculptDataTexture.wrapT = THREE.RepeatWrapping;
    sharedSculptDataTexture.minFilter = THREE.LinearFilter;
    sharedSculptDataTexture.magFilter = THREE.LinearFilter;
    sharedSculptDataTexture.needsUpdate = true;
    lastSyncedSculptVersion = terrainSculptVersion;
  } else if (lastSyncedSculptVersion !== terrainSculptVersion) {
    sharedSculptDataTexture.needsUpdate = true;
    lastSyncedSculptVersion = terrainSculptVersion;
  }
  return sharedSculptDataTexture;
}

/**
 * Exact spherical directional light direction from Blitz's Oi (LightingManager):
 * radius = 50, phi = 0.63, theta = 0.72
 */
export function getBlitzDefaultLightDirection(): THREE.Vector3 {
  const spherical = new THREE.Spherical(50, 0.63, 0.72);
  return new THREE.Vector3().setFromSpherical(spherical).normalize();
}

/**
 * Procedural 128x128 3-octave Perlin wind noise texture
 */
export function createBlitzWindNoiseTexture(): THREE.CanvasTexture {
  const canvas = document.createElement('canvas');
  canvas.width = 128;
  canvas.height = 128;
  const ctx = canvas.getContext('2d')!;
  const imgData = ctx.createImageData(128, 128);
  const data = imgData.data;

  // Deterministic seed table so wind waves are reproducible
  const table: number[] = [];
  let s = 1337420;
  for (let i = 0; i < 256; i++) {
    s = (s * 1664525 + 1013904223) >>> 0;
    table.push(s / 4294967296);
  }
  const sampleGrid = (x: number, y: number) => {
    const gx = ((x % 16) + 16) % 16;
    const gy = ((y % 16) + 16) % 16;
    return table[gy * 16 + gx];
  };
  const lerp = (a: number, b: number, t: number) => a + (b - a) * t;
  const fade = (t: number) => t * t * t * (t * (t * 6 - 15) + 10);
  const noise2D = (x: number, y: number) => {
    const ix = Math.floor(x);
    const iy = Math.floor(y);
    const fx = fade(x - ix);
    const fy = fade(y - iy);
    const a = sampleGrid(ix, iy);
    const b = sampleGrid(ix + 1, iy);
    const c = sampleGrid(ix, iy + 1);
    const d = sampleGrid(ix + 1, iy + 1);
    return lerp(lerp(a, b, fx), lerp(c, d, fx), fy);
  };

  for (let y = 0; y < 128; y++) {
    const ty = (y / 128) * 16;
    for (let x = 0; x < 128; x++) {
      const tx = (x / 128) * 16;
      let val = noise2D(tx, ty) * 0.5;
      val += noise2D(tx * 2, ty * 2) * 0.25;
      val += noise2D(tx * 4, ty * 4) * 0.125;
      const byteVal = Math.floor((val / 0.875) * 255);
      const idx = (y * 128 + x) * 4;
      data[idx] = byteVal;
      data[idx + 1] = byteVal;
      data[idx + 2] = byteVal;
      data[idx + 3] = 255;
    }
  }
  ctx.putImageData(imgData, 0, 0);
  const tex = new THREE.CanvasTexture(canvas);
  tex.wrapS = THREE.RepeatWrapping;
  tex.wrapT = THREE.RepeatWrapping;
  tex.minFilter = THREE.LinearFilter;
  tex.magFilter = THREE.LinearFilter;
  tex.needsUpdate = true;
  return tex;
}

/**
 * Fallback procedural leaf cluster alpha texture matching /assets/terrain/tree-foliage.ktx2
 * (used while KTX2 loads or if KTX2 transcoding is unavailable on software WebGL).
 */
export function createFallbackFoliageMaskTexture(): THREE.CanvasTexture {
  const canvas = document.createElement('canvas');
  canvas.width = 256;
  canvas.height = 256;
  const ctx = canvas.getContext('2d')!;
  ctx.fillStyle = '#000000';
  ctx.fillRect(0, 0, 256, 256);

  ctx.fillStyle = '#ffffff';
  const blobs = [
    [128, 128, 72],
    [82, 108, 52],
    [174, 108, 52],
    [94, 162, 50],
    [164, 162, 50],
    [128, 78, 54],
    [66, 138, 42],
    [190, 138, 42],
  ];
  for (const [bx, by, br] of blobs) {
    const grad = ctx.createRadialGradient(bx, by, br * 0.35, bx, by, br);
    grad.addColorStop(0, 'rgba(255,255,255,1)');
    grad.addColorStop(0.75, 'rgba(220,220,220,0.92)');
    grad.addColorStop(1, 'rgba(0,0,0,0)');
    ctx.fillStyle = grad;
    ctx.beginPath();
    ctx.arc(bx, by, br, 0, Math.PI * 2);
    ctx.fill();
  }
  const tex = new THREE.CanvasTexture(canvas);
  tex.wrapS = THREE.ClampToEdgeWrapping;
  tex.wrapT = THREE.ClampToEdgeWrapping;
  tex.minFilter = THREE.LinearFilter;
  tex.magFilter = THREE.LinearFilter;
  tex.generateMipmaps = false;
  tex.needsUpdate = true;
  return tex;
}

/**
 * Cel-shaded WorldMaterial shader builder:
 * Extends MeshStandardMaterial/MeshToonMaterial or ShaderMaterial with:
 * - uShadowStep = 0.15, uHighlightStep = 0.60, uShadowColor = #2a2b36
 * - 45-degree rotated Halftone dot grid (scale 180) & Cross-Hatching in core shadows
 * - Ground bounce light (bounceColor = #82487f / #75d424 grass bounce within 1.5m of ground)
 */
const blitzWorldMaterialCache = new WeakMap<BlitzWindUniforms, Map<string, THREE.ShaderMaterial>>();

export function upgradeMeshToBlitzWorldMaterial(
  mesh: THREE.Mesh,
  windUniforms: BlitzWindUniforms,
  tintHex?: string,
  bounceStrength = 0.35,
) {
  const rawMat = Array.isArray(mesh.material) ? mesh.material[0] : mesh.material;
  if ((rawMat as THREE.ShaderMaterial)?.isShaderMaterial && (rawMat as THREE.ShaderMaterial)?.uniforms?.uBaseColor) {
    return;
  }
  const srcMat = rawMat as THREE.MeshStandardMaterial;
  if (srcMat && srcMat.transparent) {
    return;
  }
  const mapTex = srcMat && srcMat.map ? srcMat.map : null;
  if (mapTex) {
    mapTex.colorSpace = THREE.SRGBColorSpace;
  }

  const baseColor = tintHex
    ? new THREE.Color(tintHex)
    : srcMat && srcMat.color
    ? srcMat.color.clone()
    : new THREE.Color('#ffffff');

  let uniformCache = blitzWorldMaterialCache.get(windUniforms);
  if (!uniformCache) {
    uniformCache = new Map<string, THREE.ShaderMaterial>();
    blitzWorldMaterialCache.set(windUniforms, uniformCache);
  }
  const cacheKey = `${baseColor.getHexString()}_${mapTex ? mapTex.uuid : 'nomap'}_${bounceStrength.toFixed(3)}`;
  let mat = uniformCache.get(cacheKey);

  if (!mat) {
    mat = new THREE.ShaderMaterial({
      uniforms: {
        uMap: { value: mapTex },
        uHasMap: { value: mapTex ? 1.0 : 0.0 },
        uBaseColor: { value: baseColor },
        uShadowColor: { value: new THREE.Color('#2a2b36') },
        uBounceColor: { value: new THREE.Color('#75d424') },
        uBounceStrength: { value: bounceStrength },
        uLightDirection: windUniforms.uLightDirection,
        uLightColor: windUniforms.uLightColor,
        uShadowStep: { value: 0.15 },
        uHighlightStep: { value: 0.6 },
        uEmissive: { value: new THREE.Color('#000000') },
      },
      vertexShader: /* glsl */ `
        varying vec2 vUv;
        varying vec3 vWorldNormal;
        varying vec3 vWorldPos;
        void main() {
          vUv = uv;
          #ifdef USE_INSTANCING
            mat4 worldMat = modelMatrix * instanceMatrix;
          #else
            mat4 worldMat = modelMatrix;
          #endif
          vec4 worldPosition = worldMat * vec4(position, 1.0);
          vWorldPos = worldPosition.xyz;
          vWorldNormal = normalize(mat3(worldMat) * normal);
          gl_Position = projectionMatrix * viewMatrix * worldPosition;
        }
      `,
      fragmentShader: /* glsl */ `
        uniform sampler2D uMap;
        uniform float uHasMap;
        uniform vec3 uBaseColor;
        uniform vec3 uShadowColor;
        uniform vec3 uBounceColor;
        uniform float uBounceStrength;
        uniform vec3 uLightDirection;
        uniform vec3 uLightColor;
        uniform float uShadowStep;
        uniform float uHighlightStep;
        uniform vec3 uEmissive;

        varying vec2 vUv;
        varying vec3 vWorldNormal;
        varying vec3 vWorldPos;

        // 45-degree halftone dot grid for cel-shaded shadow transitions
        float blitzHalftone(vec2 coord, float scale, float radius) {
          float c = cos(0.785398);
          float s = sin(0.785398);
          vec2 rot = vec2(coord.x * c - coord.y * s, coord.x * s + coord.y * c) * scale;
          float dist = length(fract(rot) - 0.5);
          float r = radius * 0.7071;
          return smoothstep(r - 0.08, r + 0.08, dist);
        }

        void main() {
          vec3 albedo = uBaseColor;
          if (uHasMap > 0.5) {
            vec4 texCol = texture2D(uMap, vUv);
            albedo *= texCol.rgb;
          }

          vec3 N = normalize(vWorldNormal);
          vec3 L = normalize(uLightDirection);
          float ndl = dot(N, L);

          // Cel-shaded step (uShadowStep = 0.15, uHighlightStep = 0.60)
          float litFactor = clamp((ndl - uShadowStep) / max(0.001, uHighlightStep - uShadowStep), 0.0, 1.0);
          float shadowFactor = 1.0 - litFactor;

          // Ground bounce light from Blitz's Yn.initOutputNode (lightBounceDistance = 1.5, lightBounceMultiplier = 0.4)
          float downFacing = smoothstep(-0.2, 0.85, -N.y);
          float heightAtten = clamp(1.0 - max(vWorldPos.y, 0.0) / 1.8, 0.0, 1.0);
          float bounceAmt = downFacing * heightAtten * heightAtten * uBounceStrength;
          vec3 colorWithBounce = mix(albedo, uBounceColor, bounceAmt);

          // Subtle cel-shaded shadow modulation (avoids large polka-dot holes on solid crate faces)
          vec2 screenCoord = gl_FragCoord.xy * 0.0045;
          float dots = blitzHalftone(screenCoord, 34.0, shadowFactor * 0.45);
          float shadowBlend = clamp(shadowFactor * (1.0 - dots * 0.06), 0.0, 1.0) * 0.62;

          vec3 litColor = colorWithBounce * uLightColor * (0.95 + 0.12 * litFactor);
          vec3 shadedColor = colorWithBounce * mix(vec3(0.66, 0.68, 0.74), uShadowColor * 1.45, 0.48);
          vec3 finalRgb = mix(litColor, shadedColor, shadowBlend) + uEmissive;

          gl_FragColor = vec4(finalRgb, 1.0);
          #include <tonemapping_fragment>
          #include <colorspace_fragment>
        }
      `,
      side: THREE.DoubleSide,
    });
    uniformCache.set(cacheKey, mat);
  }

  mesh.material = mat;
}

/**
 * Port of Blitz's StrokeManager.prototype.initStrokeGeometry & Nn (StrokeMaterial)
 * Merges vertices with tolerance 1e-4, recomputes smooth normals, and extrudes BackSide along normal.
 */
const blitzStrokeMaterialCache = new Map<string, THREE.ShaderMaterial>();

export function createBlitzStrokeMesh(
  sourceGeometry: THREE.BufferGeometry,
  strokeWidth = 0.032,
  strokeColorHex = '#12121e',
): THREE.Mesh | null {
  if (!sourceGeometry || !sourceGeometry.attributes.position) return null;
  try {
    let merged = sourceGeometry.userData.__blitzMergedStrokeGeo as THREE.BufferGeometry | undefined;
    if (!merged) {
      const cloned = sourceGeometry.clone();
      Object.keys(cloned.attributes).forEach((attr) => {
        if (attr !== 'position' && attr !== 'uv') {
          cloned.deleteAttribute(attr);
        }
      });
      cloned.clearGroups();
      merged = mergeVertices(cloned, 1e-4);
      cloned.dispose();
      merged.computeVertexNormals();
      sourceGeometry.userData.__blitzMergedStrokeGeo = merged;
    }

    const matKey = `${strokeWidth.toFixed(4)}_${strokeColorHex}`;
    let strokeMat = blitzStrokeMaterialCache.get(matKey);
    if (!strokeMat) {
      strokeMat = new THREE.ShaderMaterial({
        uniforms: {
          uStrokeWidth: { value: strokeWidth },
          uStrokeColor: { value: new THREE.Color(strokeColorHex) },
        },
        vertexShader: /* glsl */ `
          uniform float uStrokeWidth;
          void main() {
            vec3 extruded = position + normalize(normal) * uStrokeWidth;
            #ifdef USE_INSTANCING
              gl_Position = projectionMatrix * modelViewMatrix * instanceMatrix * vec4(extruded, 1.0);
            #else
              gl_Position = projectionMatrix * modelViewMatrix * vec4(extruded, 1.0);
            #endif
          }
        `,
        fragmentShader: /* glsl */ `
          uniform vec3 uStrokeColor;
          void main() {
            gl_FragColor = vec4(uStrokeColor, 1.0);
          }
        `,
        side: THREE.BackSide,
        depthWrite: true,
      });
      blitzStrokeMaterialCache.set(matKey, strokeMat);
    }

    const strokeMesh = new THREE.Mesh(merged, strokeMat);
    strokeMesh.name = 'BlitzModelStroke';
    strokeMesh.castShadow = false;
    strokeMesh.receiveShadow = false;
    strokeMesh.userData.isModelStroke = true;
    return strokeMesh;
  } catch {
    return null;
  }
}

let sharedBakedStrokeMat: THREE.MeshBasicMaterial | null = null;
function getSharedBakedStrokeMaterial(): THREE.MeshBasicMaterial {
  if (!sharedBakedStrokeMat) {
    sharedBakedStrokeMat = new THREE.MeshBasicMaterial({
      color: 0x12121e,
      side: THREE.BackSide,
    });
  }
  return sharedBakedStrokeMat;
}

function flipNonIndexedGeometryWinding(geo: THREE.BufferGeometry): void {
  const pos = geo.getAttribute('position');
  if (!pos) return;
  const norm = geo.getAttribute('normal');
  const uv = geo.getAttribute('uv');
  for (let i = 0; i + 2 < pos.count; i += 3) {
    const x1 = pos.getX(i + 1), y1 = pos.getY(i + 1), z1 = pos.getZ(i + 1);
    const x2 = pos.getX(i + 2), y2 = pos.getY(i + 2), z2 = pos.getZ(i + 2);
    pos.setXYZ(i + 1, x2, y2, z2);
    pos.setXYZ(i + 2, x1, y1, z1);
    if (norm) {
      const nx1 = norm.getX(i + 1), ny1 = norm.getY(i + 1), nz1 = norm.getZ(i + 1);
      const nx2 = norm.getX(i + 2), ny2 = norm.getY(i + 2), nz2 = norm.getZ(i + 2);
      norm.setXYZ(i + 1, nx2, ny2, nz2);
      norm.setXYZ(i + 2, nx1, ny1, nz1);
    }
    if (uv) {
      const u1 = uv.getX(i + 1), v1 = uv.getY(i + 1);
      const u2 = uv.getX(i + 2), v2 = uv.getY(i + 2);
      uv.setXY(i + 1, u2, v2);
      uv.setXY(i + 2, u1, v1);
    }
  }
}

/**
 * Merges static child meshes of `rootGroup` by shared material and merges all `BlitzModelStroke`
 * outline meshes into a single BackSide stroke mesh, cutting draw calls by 85-95% while preserving
 * excluded animated sub-groups (`excludeObjects`).
 */
const bakedVertexColorWorldMatCache = new WeakMap<object, THREE.ShaderMaterial>();

function getOrCreateBakedVertexColorWorldMaterial(
  srcMat: THREE.ShaderMaterial,
): THREE.ShaderMaterial {
  const lightDirUniform = srcMat.uniforms?.uLightDirection;
  const cacheKeyObj = (lightDirUniform && typeof lightDirUniform === 'object' ? lightDirUniform : srcMat) as object;
  let cached = bakedVertexColorWorldMatCache.get(cacheKeyObj);
  if (cached) return cached;

  cached = new THREE.ShaderMaterial({
    uniforms: {
      uShadowColor: { value: new THREE.Color('#2a2b36') },
      uBounceColor: { value: new THREE.Color('#75d424') },
      uLightDirection: srcMat.uniforms.uLightDirection,
      uLightColor: srcMat.uniforms.uLightColor,
      uShadowStep: { value: 0.15 },
      uHighlightStep: { value: 0.6 },
    },
    vertexShader: /* glsl */ `
      attribute vec4 aColorAndBounce;
      varying vec3 vBaseColor;
      varying float vBounceStrength;
      varying vec3 vWorldNormal;
      varying vec3 vWorldPos;
      void main() {
        vBaseColor = aColorAndBounce.rgb;
        vBounceStrength = aColorAndBounce.a;
        #ifdef USE_INSTANCING
          mat4 worldMat = modelMatrix * instanceMatrix;
        #else
          mat4 worldMat = modelMatrix;
        #endif
        vec4 worldPosition = worldMat * vec4(position, 1.0);
        vWorldPos = worldPosition.xyz;
        vWorldNormal = normalize(mat3(worldMat) * normal);
        gl_Position = projectionMatrix * viewMatrix * worldPosition;
      }
    `,
    fragmentShader: /* glsl */ `
      uniform vec3 uShadowColor;
      uniform vec3 uBounceColor;
      uniform vec3 uLightDirection;
      uniform vec3 uLightColor;
      uniform float uShadowStep;
      uniform float uHighlightStep;

      varying vec3 vBaseColor;
      varying float vBounceStrength;
      varying vec3 vWorldNormal;
      varying vec3 vWorldPos;

      float blitzHalftone(vec2 coord, float scale, float radius) {
        float c = cos(0.785398);
        float s = sin(0.785398);
        vec2 rot = vec2(coord.x * c - coord.y * s, coord.x * s + coord.y * c) * scale;
        float dist = length(fract(rot) - 0.5);
        float r = radius * 0.7071;
        return smoothstep(r - 0.08, r + 0.08, dist);
      }

      void main() {
        vec3 albedo = vBaseColor;
        vec3 N = normalize(vWorldNormal);
        vec3 L = normalize(uLightDirection);
        float ndl = dot(N, L);

        float litFactor = clamp((ndl - uShadowStep) / max(0.001, uHighlightStep - uShadowStep), 0.0, 1.0);
        float shadowFactor = 1.0 - litFactor;

        float downFacing = smoothstep(-0.2, 0.85, -N.y);
        float heightAtten = clamp(1.0 - max(vWorldPos.y, 0.0) / 1.8, 0.0, 1.0);
        float bounceAmt = downFacing * heightAtten * heightAtten * vBounceStrength;
        vec3 colorWithBounce = mix(albedo, uBounceColor, bounceAmt);

        vec2 screenCoord = gl_FragCoord.xy * 0.0045;
        float dots = blitzHalftone(screenCoord, 34.0, shadowFactor * 0.45);
        float shadowBlend = clamp(shadowFactor * (1.0 - dots * 0.06), 0.0, 1.0) * 0.62;

        vec3 litColor = colorWithBounce * uLightColor * (0.95 + 0.12 * litFactor);
        vec3 shadedColor = colorWithBounce * mix(vec3(0.66, 0.68, 0.74), uShadowColor * 1.45, 0.48);
        vec3 finalRgb = mix(litColor, shadedColor, shadowBlend);

        gl_FragColor = vec4(finalRgb, 1.0);
        #include <tonemapping_fragment>
        #include <colorspace_fragment>
      }
    `,
    side: THREE.DoubleSide,
  });
  cached.userData.isBakedVertexColorWorldMat = true;
  bakedVertexColorWorldMatCache.set(cacheKeyObj, cached);
  return cached;
}

export function bakeStaticGroupMeshes(
  rootGroup: THREE.Object3D,
  options?: {
    excludeObjects?: Set<THREE.Object3D>;
    minShadowCasterSpan?: number;
  },
): void {
  const excludeSet = options?.excludeObjects;
  const minShadowSpan = options?.minShadowCasterSpan ?? 0;

  rootGroup.updateMatrixWorld(true);
  const rootInv = rootGroup.matrixWorld.clone().invert();

  const materialBuckets = new Map<
    string,
    {
      material: THREE.Material;
      castShadow: boolean;
      receiveShadow: boolean;
      geos: THREE.BufferGeometry[];
    }
  >();
  const strokeGeos: THREE.BufferGeometry[] = [];
  const meshesToRemove: THREE.Mesh[] = [];
  const relMatrix = new THREE.Matrix4();
  const bboxSize = new THREE.Vector3();

  const walk = (node: THREE.Object3D) => {
    if (
      node !== rootGroup &&
      (!node.visible || excludeSet?.has(node) || isBlitzColliderOrHelperNode(node))
    ) {
      return;
    }
    if (
      node !== rootGroup &&
      node instanceof THREE.Mesh &&
      !(node instanceof THREE.InstancedMesh) &&
      node.geometry &&
      !Array.isArray(node.material)
    ) {
      relMatrix.multiplyMatrices(rootInv, node.matrixWorld);
      const isNegativeDet = relMatrix.determinant() < 0;

      if (node.userData?.isModelStroke) {
        const g = node.geometry.index ? node.geometry.toNonIndexed() : node.geometry.clone();
        const pos = g.getAttribute('position');
        if (pos && pos.count > 0) {
          if (node.name !== 'BlitzBakedStrokeMesh') {
            if (!g.getAttribute('normal')) {
              g.computeVertexNormals();
            }
            const norm = g.getAttribute('normal');
            const strokeWidth =
              (node.material as THREE.ShaderMaterial)?.uniforms?.uStrokeWidth?.value ?? 0.032;
            if (norm) {
              for (let i = 0; i < pos.count; i++) {
                const nx = norm.getX(i);
                const ny = norm.getY(i);
                const nz = norm.getZ(i);
                const len = Math.hypot(nx, ny, nz) || 1;
                pos.setXYZ(
                  i,
                  pos.getX(i) + (nx / len) * strokeWidth,
                  pos.getY(i) + (ny / len) * strokeWidth,
                  pos.getZ(i) + (nz / len) * strokeWidth,
                );
              }
            }
          }
          for (const attrName of Object.keys(g.attributes)) {
            if (attrName !== 'position') {
              g.deleteAttribute(attrName);
            }
          }
          if (isNegativeDet) {
            flipNonIndexedGeometryWinding(g);
          }
          g.applyMatrix4(relMatrix);
          strokeGeos.push(g);
          meshesToRemove.push(node);
        } else {
          g.dispose();
        }
      } else {
        const g = node.geometry.index ? node.geometry.toNonIndexed() : node.geometry.clone();
        const pos = g.getAttribute('position');
        if (pos && pos.count > 0) {
          if (!g.getAttribute('normal')) {
            g.computeVertexNormals();
          }
          if (!g.getAttribute('uv')) {
            g.setAttribute(
              'uv',
              new THREE.BufferAttribute(new Float32Array(pos.count * 2), 2),
            );
          }
          let mat = node.material as THREE.Material;
          const shaderMat = mat as THREE.ShaderMaterial;
          const isAlreadyBakedVCol = Boolean(
            mat.userData?.isBakedVertexColorWorldMat && g.getAttribute('aColorAndBounce'),
          );
          const isUntexturedWorldShader = Boolean(
            !isAlreadyBakedVCol &&
              shaderMat.isShaderMaterial &&
              shaderMat.uniforms?.uBaseColor?.value &&
              shaderMat.uniforms?.uLightDirection &&
              (shaderMat.uniforms?.uHasMap?.value ?? 0) < 0.5,
          );

          if (isUntexturedWorldShader) {
            const baseCol = shaderMat.uniforms.uBaseColor.value as THREE.Color;
            const bounceVal = Number(shaderMat.uniforms.uBounceStrength?.value ?? 0.35);
            const colBounceArr = new Float32Array(pos.count * 4);
            const r = baseCol.r;
            const gr = baseCol.g;
            const b = baseCol.b;
            for (let i = 0; i < pos.count; i++) {
              const idx = i * 4;
              colBounceArr[idx] = r;
              colBounceArr[idx + 1] = gr;
              colBounceArr[idx + 2] = b;
              colBounceArr[idx + 3] = bounceVal;
            }
            g.setAttribute('aColorAndBounce', new THREE.BufferAttribute(colBounceArr, 4));
            mat = getOrCreateBakedVertexColorWorldMaterial(shaderMat);
          }

          const keepColorAndBounce = isAlreadyBakedVCol || isUntexturedWorldShader;
          for (const attrName of Object.keys(g.attributes)) {
            if (
              attrName !== 'position' &&
              attrName !== 'normal' &&
              attrName !== 'uv' &&
              (!keepColorAndBounce || attrName !== 'aColorAndBounce')
            ) {
              g.deleteAttribute(attrName);
            }
          }
          if (isNegativeDet) {
            flipNonIndexedGeometryWinding(g);
          }
          let castShadow = node.castShadow;
          if (castShadow && minShadowSpan > 0) {
            if (!node.geometry.boundingBox) {
              node.geometry.computeBoundingBox();
            }
            if (node.geometry.boundingBox) {
              node.geometry.boundingBox.getSize(bboxSize);
              const maxScale = relMatrix.getMaxScaleOnAxis();
              const maxSpan = Math.max(bboxSize.x, bboxSize.y, bboxSize.z) * maxScale;
              if (maxSpan < minShadowSpan) {
                castShadow = false;
              }
            }
          }
          g.applyMatrix4(relMatrix);
          const key = `${mat.uuid}_${castShadow ? 1 : 0}_${node.receiveShadow ? 1 : 0}`;
          let bucket = materialBuckets.get(key);
          if (!bucket) {
            bucket = {
              material: mat,
              castShadow,
              receiveShadow: node.receiveShadow,
              geos: [],
            };
            materialBuckets.set(key, bucket);
          }
          bucket.geos.push(g);
          meshesToRemove.push(node);
        } else {
          g.dispose();
        }
      }
    }

    for (let i = 0; i < node.children.length; i++) {
      walk(node.children[i]);
    }
  };

  walk(rootGroup);

  for (const bucket of materialBuckets.values()) {
    if (bucket.geos.length === 0) continue;
    const merged =
      bucket.geos.length === 1 ? bucket.geos[0].clone() : mergeGeometries(bucket.geos, false);
    for (const g of bucket.geos) g.dispose();
    if (!merged) continue;
    merged.computeBoundingBox();
    merged.computeBoundingSphere();
    const bakedMesh = new THREE.Mesh(merged, bucket.material);
    bakedMesh.name = 'BlitzBakedStaticMesh';
    bakedMesh.castShadow = bucket.castShadow;
    bakedMesh.receiveShadow = bucket.receiveShadow;
    bakedMesh.frustumCulled = true;
    bakedMesh.matrixAutoUpdate = false;
    bakedMesh.updateMatrix();
    rootGroup.add(bakedMesh);
  }

  if (strokeGeos.length > 0) {
    const mergedStroke =
      strokeGeos.length === 1 ? strokeGeos[0].clone() : mergeGeometries(strokeGeos, false);
    for (const g of strokeGeos) g.dispose();
    if (mergedStroke) {
      mergedStroke.computeBoundingBox();
      mergedStroke.computeBoundingSphere();
      const bakedStroke = new THREE.Mesh(mergedStroke, getSharedBakedStrokeMaterial());
      bakedStroke.name = 'BlitzBakedStrokeMesh';
      bakedStroke.castShadow = false;
      bakedStroke.receiveShadow = false;
      bakedStroke.frustumCulled = true;
      bakedStroke.matrixAutoUpdate = false;
      bakedStroke.updateMatrix();
      bakedStroke.userData.isModelStroke = true;
      rootGroup.add(bakedStroke);
    }
  }

  const candidateParents = new Set<THREE.Object3D>();
  for (const m of meshesToRemove) {
    if (m.parent && m.parent !== rootGroup) {
      candidateParents.add(m.parent);
    }
    m.parent?.remove(m);
  }
  for (const p of candidateParents) {
    let cur: THREE.Object3D | null = p;
    while (
      cur &&
      cur !== rootGroup &&
      !excludeSet?.has(cur) &&
      !cur.name &&
      cur.children.length === 0
    ) {
      const parentObj: THREE.Object3D | null = cur.parent;
      parentObj?.remove(cur);
      cur = parentObj;
    }
  }
}

export function isBlitzColliderOrHelperNode(obj: THREE.Object3D): boolean {
  const n = (obj.name || '').toLowerCase();
  return (
    n.includes('cuboid') ||
    n.includes('cylinder_fixed') ||
    n.includes('cylinder_dynamic') ||
    n.includes('cone_dynamic') ||
    n.includes('collider') ||
    n.includes('kinematic') ||
    n.includes('pc_monitor_ref') ||
    n.includes('_light') ||
    n.includes('chimney_smoke') ||
    n.startsWith('tree_foliage')
  );
}

/**
 * Toroidal GPU-instanced InfiniteGrass & InfiniteGrassPetals shader system
 */
export function createBlitzInfiniteGrassSystem(
  scene: THREE.Scene,
  windUniforms: BlitzWindUniforms,
  isSoftwareGl: boolean,
) {
  // Camera-following 42m x 42m toroidal streaming window around uViewPos for a lush grass carpet with low GPU overdraw
  const isCompact = isSoftwareGl;
  const poolRadiusChunks = 3;
  const poolDiameterChunks = poolRadiusChunks * 2 + 1;
  const chunkColumns = isCompact ? 20 : 24;
  const chunkRows = isCompact ? 18 : 22;
  const fieldSize = 42.0;
  const wrappedJitterFactor = 0.78;
  const fullCircle = Math.PI * 2;
  const nearScaleMin = 0.45;
  const nearScaleMax = 1.05;
  const bladeWidth = 0.24;
  const bladeHeight = 0.64;
  const bladeFold = 0.5;
  const bladeKeepRatio = isCompact ? 0.85 : 0.92;

  // Deterministic placement hash from Ni.prototype.getPlacementSeed & randomFromSeed
  const getPlacementSeed = (col: number, row: number, c: number, d: number) => {
    let h = 2166136261;
    h ^= Math.imul(col, 374761393);
    h = Math.imul(h, 668265263);
    h ^= Math.imul(row, 1274126177);
    h = Math.imul(h, 668265263);
    h ^= Math.imul(c + 1, 2246822519);
    h = Math.imul(h, 668265263);
    h ^= Math.imul(d + 1, 3266489917);
    return h >>> 0;
  };
  const randomFromSeed = (seed: number) => {
    let t = seed >>> 0;
    t ^= t >>> 15;
    t = Math.imul(t, 2246822519);
    t ^= t >>> 13;
    t = Math.imul(t, 3266489917);
    t ^= t >>> 16;
    return (t >>> 0) / 4294967295;
  };

  // Exact 3-row x 2-column folded blade geometry from Ni.prototype.initBladeGeometry
  const bladeRows = 3;
  const bladeColumns = 2;
  const positions = new Float32Array(bladeRows * bladeColumns * 3);
  const uvs = new Float32Array(bladeRows * bladeColumns * 2);
  const indices: number[] = [];
  let pIdx = 0;
  let uvIdx = 0;
  for (let r = 0; r < bladeRows; r++) {
    const v = r / (bladeRows - 1);
    for (let c = 0; c < bladeColumns; c++) {
      const u = c / (bladeColumns - 1);
      positions[pIdx++] = u - 0.5;
      positions[pIdx++] = v;
      positions[pIdx++] = 0;
      uvs[uvIdx++] = u;
      uvs[uvIdx++] = v;
    }
  }
  const bodyEndRow = bladeRows - 2;
  for (let r = 0; r < bladeRows - 1; r++) {
    for (let c = 0; c < bladeColumns - 1; c++) {
      const i0 = r * bladeColumns + c;
      const i1 = i0 + 1;
      const i2 = i0 + bladeColumns;
      const i3 = i2 + 1;
      indices.push(i0, i1, i3);
      if (r < bodyEndRow) {
        indices.push(i0, i3, i2);
      }
    }
  }
  const bladeGeo = new THREE.BufferGeometry();
  bladeGeo.setAttribute('position', new THREE.BufferAttribute(positions, 3));
  bladeGeo.setAttribute('uv', new THREE.BufferAttribute(uvs, 2));
  bladeGeo.setIndex(indices);
  bladeGeo.computeVertexNormals();

  // Populate instances (Ni.prototype.initNearMesh)
  const totalCols = poolDiameterChunks * chunkColumns;
  const totalRows = poolDiameterChunks * chunkRows;
  const maxCandidates = totalCols * totalRows;
  const aLocalAnchorArr = new Float32Array(maxCandidates * 2);
  const aRandomArr = new Float32Array(maxCandidates * 2);
  const aBladeShapeArr = new Float32Array(maxCandidates * 4);
  const stepX = fieldSize / totalCols;
  const stepZ = fieldSize / totalRows;

  let count = 0;
  for (let row = 0; row < totalRows; row++) {
    const baseZ = (row + 0.5) * stepZ;
    for (let col = 0; col < totalCols; col++) {
      const seed = getPlacementSeed(col, row, 0, 11);
      if (randomFromSeed(seed + 43) > bladeKeepRatio) continue;
      const r0 = randomFromSeed(seed);
      const r1 = randomFromSeed(seed + 1);
      const r2 = randomFromSeed(seed + 2);
      const px = (col + 0.5) * stepX + (r0 - 0.5) * stepX * wrappedJitterFactor;
      const pz = baseZ + (r1 - 0.5) * stepZ * wrappedJitterFactor;
      const hScale = THREE.MathUtils.lerp(nearScaleMin, nearScaleMax, r2);
      const wScale = THREE.MathUtils.lerp(0.65, 1.35, r0);
      const angle = r0 * fullCircle;

      aLocalAnchorArr[count * 2] = px;
      aLocalAnchorArr[count * 2 + 1] = pz;
      aRandomArr[count * 2] = r0;
      aRandomArr[count * 2 + 1] = r2;
      aBladeShapeArr[count * 4] = hScale;
      aBladeShapeArr[count * 4 + 1] = wScale;
      aBladeShapeArr[count * 4 + 2] = Math.cos(angle);
      aBladeShapeArr[count * 4 + 3] = Math.sin(angle);
      count++;
    }
  }

  bladeGeo.setAttribute(
    'aLocalAnchor',
    new THREE.InstancedBufferAttribute(aLocalAnchorArr.slice(0, count * 2), 2),
  );
  bladeGeo.setAttribute(
    'aRandom',
    new THREE.InstancedBufferAttribute(aRandomArr.slice(0, count * 2), 2),
  );
  bladeGeo.setAttribute(
    'aBladeShape',
    new THREE.InstancedBufferAttribute(aBladeShapeArr.slice(0, count * 4), 4),
  );

  const windNoiseTex = createBlitzWindNoiseTexture();

  // Persistent Tank Track & Footstep Trail Map (512x512 canvas covering [-130..+130]m flat Blitz arena)
  const trailSpan = 260.0;
  const trailHalfSpan = trailSpan * 0.5;
  const trailCanvas = document.createElement('canvas');
  trailCanvas.width = 512;
  trailCanvas.height = 512;
  const trailCtx = trailCanvas.getContext('2d')!;
  trailCtx.fillStyle = '#000000';
  trailCtx.fillRect(0, 0, 512, 512);
  const trailTex = new THREE.CanvasTexture(trailCanvas);
  trailTex.wrapS = THREE.ClampToEdgeWrapping;
  trailTex.wrapT = THREE.ClampToEdgeWrapping;
  trailTex.minFilter = THREE.LinearFilter;
  trailTex.magFilter = THREE.LinearFilter;
  trailTex.needsUpdate = true;

  const uPlayerPos = { value: new THREE.Vector3(0, 0, 12.5) };
  const uPlayerTrailPos = { value: new THREE.Vector3(0, 0, 12.5) };
  const uViewPos = { value: new THREE.Vector3(0, 0, 12.5) };
  const uBlastWave = { value: new THREE.Vector4(0, 0, 0.01, 0) };
  const MAX_GRASS_EXCLUSIONS = 64;
  const uExclusionCount = { value: 0 };
  const uExclusionBoxes = {
    value: Array.from({ length: MAX_GRASS_EXCLUSIONS }, () => new THREE.Vector4(9999, 9999, 0, 0)),
  };
  const uExclusionRot = {
    value: Array.from({ length: MAX_GRASS_EXCLUSIONS }, () => new THREE.Vector2(1, 0)),
  };
  const MAX_GRASS_TRAMPLERS = 24;
  const uTramplerCount = { value: 0 };
  const uTramplers = {
    value: Array.from({ length: MAX_GRASS_TRAMPLERS }, () => new THREE.Vector4(9999, 9999, 1.0, 0.0)),
  };
  const uCurvatureStrength = windUniforms.uCurvatureStrength || { value: PLANET_CURVATURE_STRENGTH };
  const uSculptMap = windUniforms.uSculptMap || { value: getOrCreateSharedSculptTexture() };
  const uDirShadowMap = windUniforms.uDirShadowMap || { value: null };
  const uDirShadowMatrix = windUniforms.uDirShadowMatrix || { value: new THREE.Matrix4() };
  const uHasDirShadow = windUniforms.uHasDirShadow || { value: 0.0 };
  windUniforms.uCurvatureStrength = uCurvatureStrength;
  windUniforms.uPlanetPivot = uViewPos;
  windUniforms.uSculptMap = uSculptMap;
  windUniforms.uDirShadowMap = uDirShadowMap;
  windUniforms.uDirShadowMatrix = uDirShadowMatrix;
  windUniforms.uHasDirShadow = uHasDirShadow;

  // Toroidal Instanced InfiniteGrass Shader
  // Sun palette: #1b6e1e root -> #75d424 mid -> #d1f542 tip
  // Shadow palette: #083d12 root -> #1a7a24 mid -> #57b825 tip
  const grassMaterial = new THREE.ShaderMaterial({
    uniforms: {
      uPlayerPos,
      uPlayerTrailPos,
      uViewPos,
      uBlastWave,
      uExclusionCount,
      uExclusionBoxes,
      uExclusionRot,
      uTramplerCount,
      uTramplers,
      uCurvatureStrength,
      uSculptMap,
      uDirShadowMap,
      uDirShadowMatrix,
      uHasDirShadow,
      uFieldSize: { value: fieldSize },
      uBladeHalfW: { value: bladeWidth * 0.5 },
      uBladeHeight: { value: bladeHeight },
      uBladeFold: { value: bladeFold },
      uBladeTipWidth: { value: 1.0 },
      uRobotRadius: { value: 0.46 },
      uBendStrength: { value: 0.35 },
      uWindNoiseTex: { value: windNoiseTex },
      uTrailTex: { value: trailTex },
      uWindPhase: windUniforms.uWindPhase,
      uWindDirection: windUniforms.uWindDirection,
      uWindStrength: windUniforms.uWindStrength,
      uWindGust: windUniforms.uWindGust,
      // Sunlit & shadowed cel-shaded grass palette
      uSunBottom: { value: new THREE.Color('#1b6e1e') },
      uSunMid: { value: new THREE.Color('#75d424') },
      uSunTop: { value: new THREE.Color('#d1f542') },
      uShadowBottom: { value: new THREE.Color('#083d12') },
      uShadowMid: { value: new THREE.Color('#1a7a24') },
      uShadowTop: { value: new THREE.Color('#57b825') },
      uFloorBlend: { value: 0.65 },
      uTrailDarkening: { value: 0.80 },
    },
    vertexShader: /* glsl */ `
      attribute vec2 aLocalAnchor;
      attribute vec2 aRandom;
      attribute vec4 aBladeShape;

      uniform vec3 uPlayerPos;
      uniform vec3 uPlayerTrailPos;
      uniform vec3 uViewPos;
      uniform vec4 uBlastWave;
      uniform int uExclusionCount;
      uniform vec4 uExclusionBoxes[64];
      uniform vec2 uExclusionRot[64];
      uniform int uTramplerCount;
      uniform vec4 uTramplers[24];
      uniform float uCurvatureStrength;
      uniform float uFieldSize;
      uniform float uBladeHalfW;
      uniform float uBladeHeight;
      uniform float uBladeFold;
      uniform float uBladeTipWidth;
      uniform float uRobotRadius;
      uniform float uBendStrength;
      uniform sampler2D uWindNoiseTex;
      uniform sampler2D uTrailTex;
      uniform float uWindPhase;
      uniform vec2 uWindDirection;
      uniform float uWindStrength;
      uniform float uWindGust;

      varying float vHeightFrac;
      varying float vTrailIntensity;
      varying vec2 vBladeUV;
      varying float vNoise;
      varying float vRandom;
      varying vec3 vWorldPos;

      ${PLANET_TERRAIN_GLSL_SNIPPET}

      vec2 getWindOffset(vec3 worldPos, float randSeed) {
        vec2 dir = normalize(uWindDirection + vec2(0.0001));
        vec2 perp = vec2(-dir.y, dir.x);
        vec2 uv1 = worldPos.xz * 0.01125 + dir * (uWindPhase * 0.0175);
        vec2 uv2 = worldPos.xz * 0.034375 - dir * (uWindPhase * 0.02975);
        float c = clamp(texture2D(uWindNoiseTex, uv1).r, 0.0, 1.0);
        float l = texture2D(uWindNoiseTex, uv2).r - 0.5;
        float d = mix(0.75, 1.35, randSeed);
        float f = sin(uWindPhase * d + randSeed * 6.2831853) * 0.08;
        float p = 1.0 + uWindGust * 1.15;
        float m = (c * 0.42 + 0.24 + f) * uWindStrength * p;
        float h = (l * 0.28 + f * 0.75) * uWindStrength * p;
        return dir * m + perp * h;
      }

      void main() {
        float halfField = uFieldSize * 0.5;
        vec3 anchor = vec3(0.0);
        anchor.x = mod(aLocalAnchor.x - uViewPos.x + halfField, uFieldSize) - halfField + uViewPos.x;
        anchor.z = mod(aLocalAnchor.y - uViewPos.z + halfField, uFieldSize) - halfField + uViewPos.z;

        float dx = anchor.x - uViewPos.x;
        float dz = anchor.z - uViewPos.z;
        float distSq = dx * dx + dz * dz;
        float distToView = sqrt(distSq);
        if (distToView >= halfField) {
          gl_Position = vec4(2.0, 2.0, 2.0, 1.0);
          return;
        }

        vec2 wp = anchor.xz;
        // Smoothstep grass density from Blitz splatmap mask:
        // 1.0 on lush green meadow & small grass tuft islands, 0.0 on warm #d6a868 dirt paths & building pads
        float density = smoothstep(0.08, 0.78, evaluateBlitzGrassMask(wp));
        if (density <= 0.001) {
          gl_Position = vec4(2.0, 2.0, 2.0, 1.0);
          return;
        }

        // Surviving grass blades are already outside lake/harbor/embankment/power-plant, so only sculpt offset applies
        vec2 sculptUv = clamp((wrapPlanetVec2(wp) + 130.0) / 260.0, 0.0, 1.0);
        anchor.y = (texture2D(uSculptMap, sculptUv).r * 255.0 - 128.0) * 0.0625;

        // Suppress grass blades underneath static Park Benches, Containers, and grounded Crates
        for (int i = 0; i < 64; i++) {
          if (i >= uExclusionCount) break;
          vec4 box = uExclusionBoxes[i];
          vec2 d = wp - box.xy;
          float maxReach = max(box.z, box.w) + 1.5;
          if (abs(d.x) > maxReach || abs(d.y) > maxReach) continue;
          vec2 rot = uExclusionRot[i];
          float alongFwd = d.x * rot.x - d.y * rot.y;
          float alongRight = d.x * rot.y + d.y * rot.x;
          vec2 q = abs(vec2(alongFwd, alongRight)) - box.zw;
          float boxDist = length(max(q, 0.0)) + min(max(q.x, q.y), 0.0);
          density *= smoothstep(0.0, 0.28, boxDist);
        }
        if (density <= 0.001) {
          gl_Position = vec4(2.0, 2.0, 2.0, 1.0);
          return;
        }

        // Sample persistent tank-track / character footstep / plane propwash trail map covering [-130..+130]m
        vec2 trailUv = vec2((wp.x + 130.0) / 260.0, 1.0 - (wp.y + 130.0) / 260.0);
        float trackCrush = texture2D(uTrailTex, clamp(trailUv, 0.0, 1.0)).r;

        float hScale = aBladeShape.x * density * mix(1.0, 0.45, trackCrush);
        float wScale = aBladeShape.y * density;
        float cosA = aBladeShape.z;
        float sinA = aBladeShape.w;

        float g = clamp(position.y, 0.0, 1.0);
        float g2 = g * g;

        // Subtle shoe-width radial grass parting directly under feet (no giant flattened circle)
        vec2 toBlade = anchor.xz - uPlayerPos.xz;
        float distToPlayer = length(toBlade);
        vec2 pushDir = toBlade / (distToPlayer + 0.001);
        float innerCrush = 1.0 - smoothstep(uRobotRadius * 0.15, uRobotRadius * 0.85, distToPlayer);
        float outerPush = (1.0 - smoothstep(uRobotRadius * 0.35, uRobotRadius * 1.35, distToPlayer)) * (1.0 - innerCrush * 0.5);
        vec2 tramplePush = pushDir * (outerPush * uBendStrength * 0.45 + innerCrush * uBendStrength * 0.55);

        // Short lagged step behind player via lightweight uniform (zero 2D Canvas or GPU texture upload cost!)
        vec2 toTrail = anchor.xz - uPlayerTrailPos.xz;
        float distToTrail = length(toTrail);
        if (distToTrail < uRobotRadius * 1.15) {
          float trailCrush = (1.0 - smoothstep(uRobotRadius * 0.12, uRobotRadius * 0.80, distToTrail)) * 0.55;
          innerCrush = max(innerCrush, trailCrush);
          tramplePush += (toTrail / (distToTrail + 0.001)) * (trailCrush * uBendStrength * 0.40);
        }

        // Multi-Unit Trampling: Active Vehicles & Characters gently part grass blades directly under their footprint
        for (int i = 0; i < 24; i++) {
          if (i >= uTramplerCount) break;
          vec4 tr = uTramplers[i];
          vec2 dTr = anchor.xz - tr.xy;
          float distTr = length(dTr);
          float rTr = max(0.30, tr.z);
          if (distTr < rTr * 1.45) {
            vec2 dirTr = dTr / (distTr + 0.001);
            float cIn = (1.0 - smoothstep(rTr * 0.15, rTr * 0.85, distTr)) * tr.w;
            float pOut = (1.0 - smoothstep(rTr * 0.35, rTr * 1.35, distTr)) * (1.0 - cIn * 0.55) * tr.w;
            innerCrush = max(innerCrush, cIn);
            tramplePush += dirTr * (pOut * uBendStrength * 0.48 + cIn * uBendStrength * 0.58);
          }
        }

        vec2 windOffset = getWindOffset(anchor, aRandom.x);
        windOffset += tramplePush;
        windOffset += vec2(cosA, sinA) * (trackCrush * 0.36);

        // Radial Explosion Shockwave Bend (pushes grass blades outward around blast center)
        if (uBlastWave.w > 0.01) {
          vec2 toBlast = anchor.xz - uBlastWave.xy;
          float blastDist = length(toBlast);
          vec2 blastDir = toBlast / (blastDist + 0.001);
          float blastBand = (1.0 - smoothstep(0.0, uBlastWave.z, blastDist)) * uBlastWave.w;
          windOffset += blastDir * (blastBand * 1.45);
          hScale *= mix(1.0, 0.16, blastBand * 0.85);
        }

        float tipWidth = mix(1.0, uBladeTipWidth, g);
        float centerFold = 1.0 - smoothstep(0.0, 0.01, abs(position.x));
        float localX = (position.x * (uBladeHalfW * 2.0) * tipWidth + g2 * (aRandom.y - 0.5) * 0.4) * wScale;
        float localY = position.y * uBladeHeight * hScale * mix(1.0, 0.65, innerCrush);
        float localZ = (centerFold * (uBladeHalfW * 2.0) * uBladeFold * tipWidth + g2 * (aRandom.x - 0.5) * 0.8) * wScale;

        float fade = (1.0 - smoothstep(uFieldSize * 0.36, uFieldSize * 0.495, distToView)) * density;
        if (fade <= 0.005) {
          gl_Position = vec4(2.0, 2.0, 2.0, 1.0);
          return;
        }

        localX *= fade;
        localY *= fade;
        localZ *= fade;

        vec3 worldPos = vec3(
          anchor.x + localX * cosA - localZ * sinA + windOffset.x * g2 * fade,
          anchor.y + localY - length(windOffset) * 0.25 * g * fade,
          anchor.z + localX * sinA + localZ * cosA + windOffset.y * g2 * fade
        );

        vHeightFrac = g;
        vTrailIntensity = clamp(trackCrush * 0.55, 0.0, 1.0);
        vBladeUV = vec2(position.x + 0.5, position.y);
        vec2 nUv = wp * 0.018;
        vNoise = texture2D(uWindNoiseTex, nUv).r * 2.0 - 1.0;
        vRandom = aRandom.x;
        vWorldPos = worldPos;

        gl_Position = projectionMatrix * viewMatrix * vec4(worldPos, 1.0);
      }
    `,
    fragmentShader: /* glsl */ `
      uniform vec3 uSunBottom;
      uniform vec3 uSunMid;
      uniform vec3 uSunTop;
      uniform vec3 uShadowBottom;
      uniform vec3 uShadowMid;
      uniform vec3 uShadowTop;
      uniform float uFloorBlend;
      uniform float uTrailDarkening;

      varying float vHeightFrac;
      varying float vTrailIntensity;
      varying vec2 vBladeUV;
      varying float vNoise;
      varying float vRandom;
      varying vec3 vWorldPos;

      ${BLITZ_CAST_SHADOW_GLSL_SNIPPET}

      void main() {
        float patchFactor = smoothstep(0.18, 0.78, clamp(vNoise * 0.5 + 0.5, 0.0, 1.0));
        // Fast single-tap directional shadow lookup per grass blade (naturally anti-aliased across dense blades)
        float castShadow = 1.0;
        if (uHasDirShadow > 0.5) {
          vec4 sc = uDirShadowMatrix * vec4(vWorldPos, 1.0);
          sc.xyz /= sc.w;
          if (sc.x > 0.002 && sc.x < 0.998 && sc.y > 0.002 && sc.y < 0.998 && sc.z > 0.0 && sc.z < 1.0) {
            castShadow = step(sc.z - 0.0014, texture2D(uDirShadowMap, sc.xy).r);
          }
        }
        float litFactor = patchFactor * mix(0.12, 1.0, castShadow);

        vec3 bottomCol = mix(uShadowBottom, uSunBottom, litFactor);
        vec3 midCol = mix(uShadowMid, uSunMid, litFactor);
        vec3 topCol = mix(uShadowTop, uSunTop, litFactor);

        vec3 col = mix(mix(mix(bottomCol, midCol, uFloorBlend), midCol, 0.5), midCol, smoothstep(0.0, 0.5, vHeightFrac));
        col = mix(col, topCol, smoothstep(0.5, 1.0, vHeightFrac));
        col *= 1.0 + (vRandom - 0.5) * 0.1;
        col *= mix(0.9, 1.12, step(0.5, vBladeUV.x));

        vec3 trailCol = mix(uShadowBottom, vec3(0.078, 0.349, 0.251), 0.6);
        col = mix(col, trailCol, vTrailIntensity * 0.85);

        gl_FragColor = vec4(col, 1.0);
        #include <tonemapping_fragment>
        #include <colorspace_fragment>
      }
    `,
    side: THREE.DoubleSide,
  });

  const grassMesh = new THREE.InstancedMesh(bladeGeo, grassMaterial, count);
  grassMesh.name = 'InfiniteGrass';
  grassMesh.frustumCulled = false;
  grassMesh.castShadow = false;
  grassMesh.receiveShadow = true;
  grassMesh.matrixAutoUpdate = false;
  grassMesh.updateMatrix();
  const ident = new THREE.Matrix4().identity();
  for (let i = 0; i < count; i++) {
    grassMesh.setMatrixAt(i, ident);
  }
  grassMesh.instanceMatrix.needsUpdate = true;
  scene.add(grassMesh);

  // Colorful Flower/Petal Specks nestled inside the grass
  // Small crisp diamond/square flower specks (#fff04a, #ffb300, #b366ff, #ff5c8a, #38bdf8) swaying with the wind
  const petalCount = isCompact ? 520 : 680;
  const petalGeo = new THREE.PlaneGeometry(1, 1);
  petalGeo.rotateX(-Math.PI / 2);
  const petalAnchorArr = new Float32Array(petalCount * 3);
  const petalRandomArr = new Float32Array(petalCount * 4);
  const petalColorArr = new Float32Array(petalCount);

  for (let i = 0; i < petalCount; i++) {
    const s = getPlacementSeed(i, 0, i, 29);
    const n = randomFromSeed(s);
    const r = randomFromSeed(s + 1);
    const k = randomFromSeed(s + 2);
    const a = randomFromSeed(s + 3);
    const c = randomFromSeed(s + 4);
    petalAnchorArr[i * 3] = n * fieldSize;
    petalAnchorArr[i * 3 + 1] = 0;
    petalAnchorArr[i * 3 + 2] = r * fieldSize;
    petalRandomArr[i * 4] = n;
    petalRandomArr[i * 4 + 1] = r;
    petalRandomArr[i * 4 + 2] = k;
    petalRandomArr[i * 4 + 3] = a;
    petalColorArr[i] = c;
  }
  petalGeo.setAttribute('aPetalAnchor', new THREE.InstancedBufferAttribute(petalAnchorArr, 3));
  petalGeo.setAttribute('aPetalRandom', new THREE.InstancedBufferAttribute(petalRandomArr, 4));
  petalGeo.setAttribute('aPetalColor', new THREE.InstancedBufferAttribute(petalColorArr, 1));

  const petalMat = new THREE.ShaderMaterial({
    uniforms: {
      uPlayerPos,
      uPlayerTrailPos,
      uViewPos,
      uExclusionCount,
      uExclusionBoxes,
      uExclusionRot,
      uSculptMap,
      uFieldSize: { value: fieldSize },
      uPetalSize: { value: 0.22 },
      uBladeHeight: { value: bladeHeight },
      uRobotRadius: { value: 2.35 },
      uWindNoiseTex: { value: windNoiseTex },
      uWindPhase: windUniforms.uWindPhase,
      uWindDirection: windUniforms.uWindDirection,
      uWindStrength: windUniforms.uWindStrength,
      uWindGust: windUniforms.uWindGust,
      uPetalColor0: { value: new THREE.Color('#fff04a') },
      uPetalColor1: { value: new THREE.Color('#ffb300') },
      uPetalColor2: { value: new THREE.Color('#b366ff') },
      uPetalColor3: { value: new THREE.Color('#ff5c8a') },
      uPetalColor4: { value: new THREE.Color('#38bdf8') },
    },
    vertexShader: /* glsl */ `
      attribute vec3 aPetalAnchor;
      attribute vec4 aPetalRandom;
      attribute float aPetalColor;
      uniform vec3 uPlayerPos;
      uniform vec3 uPlayerTrailPos;
      uniform vec3 uViewPos;
      uniform int uExclusionCount;
      uniform vec4 uExclusionBoxes[64];
      uniform vec2 uExclusionRot[64];
      uniform float uFieldSize;
      uniform float uPetalSize;
      uniform float uBladeHeight;
      uniform float uRobotRadius;
      uniform sampler2D uWindNoiseTex;
      uniform float uWindPhase;
      uniform vec2 uWindDirection;
      uniform float uWindStrength;
      uniform float uWindGust;
      varying float vColorSeed;

      ${PLANET_TERRAIN_GLSL_SNIPPET}

      vec2 getWindOffset(vec3 worldPos, float randSeed) {
        vec2 dir = normalize(uWindDirection + vec2(0.0001));
        vec2 perp = vec2(-dir.y, dir.x);
        vec2 uv1 = worldPos.xz * 0.01125 + dir * (uWindPhase * 0.0175);
        vec2 uv2 = worldPos.xz * 0.034375 - dir * (uWindPhase * 0.02975);
        float c = clamp(texture2D(uWindNoiseTex, uv1).r, 0.0, 1.0);
        float l = texture2D(uWindNoiseTex, uv2).r - 0.5;
        float d = mix(0.75, 1.35, randSeed);
        float f = sin(uWindPhase * d + randSeed * 6.2831853) * 0.08;
        float p = 1.0 + uWindGust * 1.15;
        float m = (c * 0.42 + 0.24 + f) * uWindStrength * p;
        float h = (l * 0.28 + f * 0.75) * uWindStrength * p;
        return dir * m + perp * h;
      }

      void main() {
        float halfField = uFieldSize * 0.5;
        vec3 anchor = vec3(0.0);
        anchor.x = mod(aPetalAnchor.x - uViewPos.x + halfField, uFieldSize) - halfField + uViewPos.x;
        anchor.z = mod(aPetalAnchor.z - uViewPos.z + halfField, uFieldSize) - halfField + uViewPos.z;
        float distToView = length(anchor.xz - uViewPos.xz);
        if (distToView >= halfField) {
          gl_Position = vec4(2.0, 2.0, 2.0, 1.0);
          return;
        }

        // Only grow flower specks where grass grows!
        float density = smoothstep(0.25, 0.82, evaluateBlitzGrassMask(anchor.xz));
        if (density <= 0.001) {
          gl_Position = vec4(2.0, 2.0, 2.0, 1.0);
          return;
        }
        anchor.y = getRawGroundElevation(anchor.xz);

        for (int i = 0; i < 64; i++) {
          if (i >= uExclusionCount) break;
          vec4 box = uExclusionBoxes[i];
          vec2 d = anchor.xz - box.xy;
          float maxReach = max(box.z, box.w) + 1.5;
          if (abs(d.x) > maxReach || abs(d.y) > maxReach) continue;
          vec2 rot = uExclusionRot[i];
          float alongFwd = d.x * rot.x - d.y * rot.y;
          float alongRight = d.x * rot.y + d.y * rot.x;
          vec2 q = abs(vec2(alongFwd, alongRight)) - box.zw;
          float boxDist = length(max(q, 0.0)) + min(max(q.x, q.y), 0.0);
          density *= smoothstep(0.0, 0.28, boxDist);
        }
        if (density <= 0.001) {
          gl_Position = vec4(2.0, 2.0, 2.0, 1.0);
          return;
        }

        float fade = (1.0 - smoothstep(uFieldSize * 0.36, uFieldSize * 0.495, distToView)) * density;
        if (fade <= 0.005) {
          gl_Position = vec4(2.0, 2.0, 2.0, 1.0);
          return;
        }

        float distToPlayer = length(anchor.xz - uPlayerPos.xz);
        float playerHide = smoothstep(uRobotRadius * 0.25, uRobotRadius * 1.35, distToPlayer);
        fade *= playerHide;

        float yaw = aPetalRandom.x * 6.2831853;
        float tiltX = (aPetalRandom.y - 0.5) * 1.1;
        float tiltZ = (aPetalRandom.z - 0.5) * 1.1;
        float scale = uPetalSize * (0.65 + aPetalRandom.w * 0.75) * fade;

        vec3 p = position * scale;
        float cy = cos(yaw), sy = sin(yaw);
        float cx = cos(tiltX), sx = sin(tiltX);
        float cz = cos(tiltZ), sz = sin(tiltZ);
        vec3 p1 = vec3(p.x, p.y * cx - p.z * sx, p.y * sx + p.z * cx);
        vec3 p2 = vec3(p1.x * cz - p1.y * sz, p1.x * sz + p1.y * cz, p1.z);
        vec3 p3 = vec3(p2.x * cy - p2.z * sy, p2.y, p2.x * sy + p2.z * cy);

        float heightRatio = 0.16 + aPetalRandom.z * 0.52;
        vec2 wind = getWindOffset(anchor, aPetalRandom.x) * (heightRatio * heightRatio);
        vec3 worldPos = vec3(
          anchor.x + p3.x + wind.x * fade,
          anchor.y + p3.y + uBladeHeight * heightRatio * fade,
          anchor.z + p3.z + wind.y * fade
        );

        vColorSeed = aPetalColor;
        gl_Position = projectionMatrix * viewMatrix * vec4(worldPos, 1.0);
      }
    `,
    fragmentShader: /* glsl */ `
      uniform vec3 uPetalColor0;
      uniform vec3 uPetalColor1;
      uniform vec3 uPetalColor2;
      uniform vec3 uPetalColor3;
      uniform vec3 uPetalColor4;
      varying float vColorSeed;
      void main() {
        vec3 col = uPetalColor0;
        if (vColorSeed >= 0.2 && vColorSeed < 0.4) col = uPetalColor1;
        else if (vColorSeed >= 0.4 && vColorSeed < 0.6) col = uPetalColor2;
        else if (vColorSeed >= 0.6 && vColorSeed < 0.8) col = uPetalColor3;
        else if (vColorSeed >= 0.8) col = uPetalColor4;
        gl_FragColor = vec4(col, 1.0);
        #include <tonemapping_fragment>
        #include <colorspace_fragment>
      }
    `,
    side: THREE.DoubleSide,
  });

  const petalMesh = new THREE.InstancedMesh(petalGeo, petalMat, petalCount);
  petalMesh.name = 'InfiniteGrassPetals';
  petalMesh.frustumCulled = false;
  petalMesh.castShadow = false;
  petalMesh.receiveShadow = false;
  petalMesh.matrixAutoUpdate = false;
  petalMesh.updateMatrix();
  for (let i = 0; i < petalCount; i++) {
    petalMesh.setMatrixAt(i, ident);
  }
  petalMesh.instanceMatrix.needsUpdate = true;
  scene.add(petalMesh);

  let trailFadeCounter = 0;
  let trailDirty = false;
  let activeTrailFramesRemaining = 0;

  return {
    grassMesh,
    petalMesh,
    update(playerX: number, playerZ: number, viewX = playerX, viewZ = playerZ) {
      uPlayerPos.value.set(playerX, 0, playerZ);
      uViewPos.value.set(viewX, 0, viewZ);
      // Smooth short trailed step uniform (zero 2D canvas drawing & zero GPU texture upload when walking)
      const dxTrail = playerX - uPlayerTrailPos.value.x;
      const dzTrail = playerZ - uPlayerTrailPos.value.z;
      if (dxTrail * dxTrail + dzTrail * dzTrail > 9.0) {
        uPlayerTrailPos.value.set(playerX, 0, playerZ);
      } else {
        uPlayerTrailPos.value.x += dxTrail * 0.14;
        uPlayerTrailPos.value.z += dzTrail * 0.14;
      }

      trailFadeCounter++;
      if (activeTrailFramesRemaining > 0) {
        activeTrailFramesRemaining--;
        if (trailFadeCounter % 24 === 0) {
          trailCtx.fillStyle = 'rgba(0, 0, 0, 0.012)';
          trailCtx.fillRect(0, 0, 512, 512);
          trailDirty = true;
        }
      }

      if (trailDirty && trailFadeCounter % 3 === 0) {
        trailTex.needsUpdate = true;
        trailDirty = false;
      }
    },
    stampTankTracks(leftX: number, leftZ: number, rightX: number, rightZ: number) {
      const toPx = (wx: number) => ((wx + trailHalfSpan) / trailSpan) * 512;
      const toPz = (wz: number) => ((wz + trailHalfSpan) / trailSpan) * 512;
      const drawRut = (wx: number, wz: number) => {
        const cx = toPx(wx);
        const cy = toPz(wz);
        const grad = trailCtx.createRadialGradient(cx, cy, 0.8, cx, cy, 5.8);
        grad.addColorStop(0, 'rgba(255, 255, 255, 1.0)');
        grad.addColorStop(0.7, 'rgba(255, 255, 255, 0.82)');
        grad.addColorStop(1, 'rgba(255, 255, 255, 0)');
        trailCtx.fillStyle = grad;
        trailCtx.beginPath();
        trailCtx.arc(cx, cy, 5.8, 0, Math.PI * 2);
        trailCtx.fill();
      };
      drawRut(leftX, leftZ);
      drawRut(rightX, rightZ);
      trailDirty = true;
      activeTrailFramesRemaining = 720;
    },
    stampExplosionShockwave(worldX: number, worldZ: number, radiusMeters = 4.2, waveStrength = 1.0) {
      const cx = ((worldX + trailHalfSpan) / trailSpan) * 512;
      const cy = ((worldZ + trailHalfSpan) / trailSpan) * 512;
      const pxRadius = Math.max(6.0, (radiusMeters / trailSpan) * 512);
      const grad = trailCtx.createRadialGradient(cx, cy, pxRadius * 0.12, cx, cy, pxRadius);
      grad.addColorStop(0, 'rgba(255, 255, 255, 1.0)');
      grad.addColorStop(0.65, 'rgba(255, 255, 255, 0.88)');
      grad.addColorStop(1, 'rgba(255, 255, 255, 0)');
      trailCtx.fillStyle = grad;
      trailCtx.beginPath();
      trailCtx.arc(cx, cy, pxRadius, 0, Math.PI * 2);
      trailCtx.fill();
      trailTex.needsUpdate = true;
      trailDirty = false;
      activeTrailFramesRemaining = 720;
      uBlastWave.value.set(worldX, worldZ, radiusMeters * 1.35, Math.min(1.5, waveStrength));
    },
    decayBlastWave(dt: number) {
      if (uBlastWave.value.w > 0.001) {
        uBlastWave.value.w = Math.max(0, uBlastWave.value.w - dt * 2.4);
      }
    },
    setTramplers(
      items: ReadonlyArray<{
        x: number;
        z: number;
        radius: number;
        weight?: number;
      }>,
    ) {
      const n = Math.min(MAX_GRASS_TRAMPLERS, items.length);
      uTramplerCount.value = n;
      for (let i = 0; i < n; i++) {
        const it = items[i];
        uTramplers.value[i].set(it.x, it.z, Math.max(0.4, it.radius), it.weight ?? 1.0);
      }
    },
    stampFootstep(_worldX: number, _worldZ: number, _radiusMeters = 0.34) {
      // Handled via lightweight GPU uniform (uTramplers & uPlayerTrailPos) to avoid 512x512 Canvas2D redraw & GPU texture upload stalls
    },
    setDynamicExclusions(
      items: ReadonlyArray<{
        x: number;
        z: number;
        yaw: number;
        halfLen: number;
        halfWidth: number;
      }>,
    ) {
      const n = Math.min(MAX_GRASS_EXCLUSIONS, items.length);
      uExclusionCount.value = n;
      for (let i = 0; i < n; i++) {
        const it = items[i];
        uExclusionBoxes.value[i].set(it.x, it.z, it.halfLen, it.halfWidth);
        uExclusionRot.value[i].set(Math.cos(it.yaw), Math.sin(it.yaw));
      }
    },
    dispose() {
      scene.remove(grassMesh);
      scene.remove(petalMesh);
      bladeGeo.dispose();
      grassMaterial.dispose();
      petalGeo.dispose();
      petalMat.dispose();
      windNoiseTex.dispose();
      trailTex.dispose();
    },
  };
}

const cachedTreeClusterGeos = new Map<number, THREE.BufferGeometry>();
const cachedTreeMaterials = new WeakMap<
  BlitzWindUniforms,
  {
    purpleMat?: THREE.ShaderMaterial;
    greenMat?: THREE.ShaderMaterial;
    depthMat?: THREE.ShaderMaterial;
  }
>();

function getSharedTreeClusterGeometry(planesPerCluster: number): THREE.BufferGeometry {
  const existing = cachedTreeClusterGeos.get(planesPerCluster);
  if (existing) return existing;

  const planeSize = 0.8;
  const normalLerp = 0.8;
  let randomSeed = 1431691;
  const getRandom = () => {
    randomSeed = (randomSeed * 1664525 + 1013904223) >>> 0;
    return randomSeed / 4294967296;
  };

  const clusterGeos: THREE.BufferGeometry[] = [];
  const leafCenters = new Float32Array(planesPerCluster * 4 * 3);
  const leafLocalPos = new Float32Array(planesPerCluster * 4 * 3);
  const leafPlaneSeed = new Float32Array(planesPerCluster * 4);

  for (let a = 0; a < planesPerCluster; a++) {
    const plane = new THREE.PlaneGeometry(planeSize, planeSize);
    const seed = getRandom();
    const radius = 1 - Math.pow(getRandom(), 3);
    const phi = Math.PI * 2 * getRandom();
    const theta = Math.PI * getRandom();
    const sph = new THREE.Spherical(radius, theta, phi);
    const center = new THREE.Vector3().setFromSpherical(sph);
    const radialNormal = center.clone().normalize();

    const posAttr = plane.attributes.position;
    const normAttr = plane.attributes.normal;
    for (let v = 0; v < 4; v++) {
      const vertIdx = a * 4 + v;
      const s3 = v * 3;
      const f3 = vertIdx * 3;
      const p = new THREE.Vector3(posAttr.array[s3], posAttr.array[s3 + 1], posAttr.array[s3 + 2]);
      leafCenters[f3] = center.x;
      leafCenters[f3 + 1] = center.y;
      leafCenters[f3 + 2] = center.z;
      leafLocalPos[f3] = p.x;
      leafLocalPos[f3 + 1] = p.y;
      leafLocalPos[f3 + 2] = p.z;
      leafPlaneSeed[vertIdx] = seed;

      const blendedNormal = p.clone().lerp(radialNormal, normalLerp).normalize();
      normAttr.array[s3] = blendedNormal.x;
      normAttr.array[s3 + 1] = blendedNormal.y;
      normAttr.array[s3 + 2] = blendedNormal.z;
    }
    clusterGeos.push(plane);
  }

  const mergedClusterGeo = mergeGeometries(clusterGeos, false);
  clusterGeos.forEach((g) => g.dispose());
  mergedClusterGeo.setAttribute('aLeafCenter', new THREE.BufferAttribute(leafCenters, 3));
  mergedClusterGeo.setAttribute('aLeafLocalPos', new THREE.BufferAttribute(leafLocalPos, 3));
  mergedClusterGeo.setAttribute('aLeafPlaneSeed', new THREE.BufferAttribute(leafPlaneSeed, 1));
  mergedClusterGeo.boundingBox = new THREE.Box3(
    new THREE.Vector3(-6.5, -2.0, -6.5),
    new THREE.Vector3(6.5, 11.0, 6.5),
  );
  mergedClusterGeo.boundingSphere = new THREE.Sphere(new THREE.Vector3(0, 4.5, 0), 8.5);
  cachedTreeClusterGeos.set(planesPerCluster, mergedClusterGeo);
  return mergedClusterGeo;
}

let sharedFallbackFoliageMaskTex: THREE.CanvasTexture | null = null;
export function getSharedFallbackFoliageMaskTexture(): THREE.CanvasTexture {
  if (!sharedFallbackFoliageMaskTex) {
    sharedFallbackFoliageMaskTex = createFallbackFoliageMaskTexture();
  }
  return sharedFallbackFoliageMaskTex;
}

const DEFAULT_TREE_1A_MARKERS: ReadonlyArray<{ pos: [number, number, number]; scale: number }> = [
  { pos: [3.199194, 8.762081, 1.109548], scale: 1.380665 },
  { pos: [1.150006, 8.153307, 3.332199], scale: 1.744493 },
  { pos: [-1.662091, 8.742344, 2.410386], scale: 1.616032 },
  { pos: [-0.322173, 5.554489, 2.019353], scale: 1.530025 },
  { pos: [-2.012829, 7.901125, -0.343776], scale: 1.612328 },
  { pos: [0.518135, 7.112765, -1.909685], scale: 1.757379 },
  { pos: [-0.90037, 5.143407, -0.517511], scale: 1.380665 },
  { pos: [0.990456, 10.069603, -0.715984], scale: 1.90842 },
];

const DEFAULT_TREE_1B_MARKERS: ReadonlyArray<{ pos: [number, number, number]; scale: number }> = [
  { pos: [-1.326642, 9.998069, -0.517182], scale: 2.082448 },
  { pos: [-1.564714, 5.638724, 0.66546], scale: 1.55381 },
  { pos: [2.39235, 8.997023, 2.076546], scale: 2.082448 },
  { pos: [0.842955, 8.418361, -2.369225], scale: 2.445399 },
  { pos: [0.262933, 6.74558, 2.850314], scale: 1.7219 },
  { pos: [3.232309, 7.056585, -0.362566], scale: 2.18204 },
  { pos: [-0.189277, 5.601172, -1.472421], scale: 1.418981 },
  { pos: [-3.484861, 8.525259, 0.389176], scale: 1.963265 },
  { pos: [-0.464042, 9.066426, 2.037847], scale: 1.55381 },
];

/**
 * Exact port of Blitz's TreeLeaves (TreeLeaves + TreeLeavesMaterial):
 * - Merges 64 random spherical leaf planes per foliage cluster
 * - Rotates each plane to face camera with per-plane random spin
 * - Samples tree-foliage.ktx2 / createFallbackFoliageMaskTexture mask texture for crisp leaf cutout silhouette
 * - Shades with two-tone color ramp + wind sway
 */
export function populateRealBlitzTreeFromGlb(
  targetGroup: THREE.Group,
  treeGltfScene: THREE.Group | null,
  isPurpleTree: boolean,
  leafMaskTexture: THREE.Texture | null | undefined,
  windUniforms: BlitzWindUniforms,
  isSoftwareGl: boolean,
  userScale = 1.0,
) {
  const effectiveLeafMask = leafMaskTexture || getSharedFallbackFoliageMaskTexture();
  for (let i = targetGroup.children.length - 1; i >= 0; i--) {
    const ch = targetGroup.children[i];
    if (ch.name !== 'ContactShadowDisc') {
      targetGroup.remove(ch);
    } else {
      // Hide flat circular disc so real directional leaf-canopy cast shadow + halftone dot edge shines cleanly
      ch.visible = false;
    }
  }

  const trunkGroup = new THREE.Group();
  trunkGroup.name = 'RealGlbTreeTrunk';
  const foliageMarkerMatrices: THREE.Matrix4[] = [];

  if (treeGltfScene) {
    treeGltfScene.updateMatrixWorld(true);

    let refRoot: THREE.Object3D | null = null;
    treeGltfScene.traverse((obj) => {
      const n = (obj.name || '').toLowerCase();
      if (!refRoot && n.endsWith('ref')) {
        refRoot = obj;
      }
    });
    const sourceRoot = (refRoot || treeGltfScene.children[0] || treeGltfScene) as THREE.Object3D;

    const baseRefScale = sourceRoot.scale.x > 0.01 ? sourceRoot.scale.x : 0.4362676;
    const refScale = baseRefScale * 1.75 * userScale;

    if ((sourceRoot as THREE.Mesh).isMesh) {
      const srcTrunk = sourceRoot as THREE.Mesh;
      const trunkMesh = new THREE.Mesh(srcTrunk.geometry, srcTrunk.material);
      trunkMesh.name = srcTrunk.name;
      trunkMesh.scale.setScalar(refScale);
      trunkMesh.frustumCulled = true;
      trunkMesh.castShadow = true;
      trunkMesh.receiveShadow = true;
      upgradeMeshToBlitzWorldMaterial(trunkMesh, windUniforms, '#755341');
      const stroke = createBlitzStrokeMesh(trunkMesh.geometry, 0.036);
      if (stroke) {
        stroke.frustumCulled = true;
        trunkMesh.add(stroke);
      }
      trunkGroup.add(trunkMesh);
    }

    sourceRoot.traverse((child) => {
      if (child === sourceRoot) return;
      const lower = (child.name || '').toLowerCase();
      if (lower.startsWith('tree_foliage') || lower.includes('foliage')) {
        const m = new THREE.Matrix4();
        const pos = child.position.clone().multiplyScalar(refScale);
        const scl = child.scale.clone().multiplyScalar(refScale * 0.65);
        m.compose(pos, child.quaternion, scl);
        foliageMarkerMatrices.push(m);
      }
    });
  } else {
    const refScale = 0.4362676 * 1.75 * userScale;
    const addTrunkLimb = (
      geo: THREE.BufferGeometry,
      pos: [number, number, number],
      rot: [number, number, number] = [0, 0, 0],
    ) => {
      const m = new THREE.Mesh(geo, new THREE.MeshStandardMaterial({ color: '#755341' }));
      m.position.set(pos[0] * userScale, pos[1] * userScale, pos[2] * userScale);
      m.rotation.set(rot[0], rot[1], rot[2]);
      m.scale.setScalar(userScale);
      m.castShadow = true;
      m.receiveShadow = true;
      upgradeMeshToBlitzWorldMaterial(m, windUniforms, '#755341');
      const stroke = createBlitzStrokeMesh(geo, 0.032);
      if (stroke) m.add(stroke);
      trunkGroup.add(m);
    };
    addTrunkLimb(new THREE.CylinderGeometry(0.42, 0.68, 4.4, 8), [0, 2.2, 0]);
    addTrunkLimb(new THREE.CylinderGeometry(0.24, 0.38, 2.8, 7), [0.65, 4.6, 0.35], [-0.28, 0.2, -0.36]);
    addTrunkLimb(new THREE.CylinderGeometry(0.22, 0.36, 2.6, 7), [-0.58, 4.5, -0.32], [0.25, -0.3, 0.34]);

    const fallbackMarkers = isPurpleTree ? DEFAULT_TREE_1B_MARKERS : DEFAULT_TREE_1A_MARKERS;
    const dummyQ = new THREE.Quaternion();
    for (const mk of fallbackMarkers) {
      const m = new THREE.Matrix4();
      const pos = new THREE.Vector3(mk.pos[0], mk.pos[1], mk.pos[2]).multiplyScalar(refScale);
      const scl = new THREE.Vector3(mk.scale, mk.scale, mk.scale).multiplyScalar(refScale * 0.65);
      m.compose(pos, dummyQ, scl);
      foliageMarkerMatrices.push(m);
    }
  }

  const box = new THREE.Box3().setFromObject(trunkGroup);
  if (!box.isEmpty()) {
    trunkGroup.position.y = -box.min.y;
  }
  targetGroup.add(trunkGroup);

  const planesPerCluster = isSoftwareGl ? 48 : 64;
  const mergedClusterGeo = getSharedTreeClusterGeometry(planesPerCluster);

  let matCache = cachedTreeMaterials.get(windUniforms);
  if (!matCache) {
    matCache = {};
    cachedTreeMaterials.set(windUniforms, matCache);
  }

  let foliageMaterial = isPurpleTree ? matCache.purpleMat : matCache.greenMat;
  if (!foliageMaterial) {
    // Original Blitz palette: Purple/Pink (#a369ff -> #ff75d8) & Golden/Green (#2cb84b -> #ffd23f)
    const colorA = new THREE.Color(isPurpleTree ? '#a369ff' : '#2cb84b');
    const colorB = new THREE.Color(isPurpleTree ? '#ff75d8' : '#ffd23f');

    foliageMaterial = new THREE.ShaderMaterial({
      uniforms: {
        uLeafTex: { value: effectiveLeafMask },
        uColorA: { value: colorA },
        uColorB: { value: colorB },
        uLeafScale: { value: 1.38 },
        uAlphaThreshold: { value: 0.28 },
        uLightDirection: windUniforms.uLightDirection,
        uWindPhase: windUniforms.uWindPhase,
        uWindDirection: windUniforms.uWindDirection,
        uWindStrength: windUniforms.uWindStrength,
        uWindGust: windUniforms.uWindGust,
      },
      vertexShader: /* glsl */ `
        attribute vec3 aLeafCenter;
        attribute vec3 aLeafLocalPos;
        attribute float aLeafPlaneSeed;

        uniform float uLeafScale;
        uniform float uWindPhase;
        uniform vec2 uWindDirection;
        uniform float uWindStrength;
        uniform float uWindGust;

        varying vec2 vUv;
        varying vec3 vSphereNormal;

        void main() {
          vUv = uv;
          float angle = aLeafPlaneSeed * 6.2831853;
          float s = sin(angle);
          float c = cos(angle);
          vec3 scaledLocal = aLeafLocalPos * uLeafScale;
          float rotX = scaledLocal.x * c - scaledLocal.y * s;
          float rotY = scaledLocal.x * s + scaledLocal.y * c;

          mat4 mv = viewMatrix * modelMatrix * instanceMatrix;
          vec3 camRight = normalize(vec3(mv[0][0], mv[1][0], mv[2][0]));
          vec3 camUp = normalize(vec3(mv[0][1], mv[1][1], mv[2][1]));
          vec3 camFwd = normalize(vec3(mv[0][2], mv[1][2], mv[2][2]));

          float swayFactor = smoothstep(-0.75, 1.0, aLeafCenter.y);
          float phase = uWindPhase + aLeafPlaneSeed * 6.2831853;
          float sway = (sin(phase) * 0.46 + uWindGust * 0.28) * uWindStrength * swayFactor;
          vec3 windDisp = vec3(uWindDirection.x * sway, sin(phase * 0.73) * 0.1 * uWindStrength * swayFactor, uWindDirection.y * sway);

          vec3 localPos = aLeafCenter + camRight * rotX + camUp * rotY + camFwd * ((aLeafPlaneSeed - 0.5) * 0.02) + windDisp;
          vSphereNormal = normalize(mat3(modelMatrix * instanceMatrix) * normalize(aLeafCenter + vec3(0.0, 0.35, 0.0)));

          gl_Position = projectionMatrix * viewMatrix * modelMatrix * instanceMatrix * vec4(localPos, 1.0);
        }
      `,
      fragmentShader: /* glsl */ `
        uniform sampler2D uLeafTex;
        uniform vec3 uColorA;
        uniform vec3 uColorB;
        uniform float uAlphaThreshold;
        uniform vec3 uLightDirection;

        varying vec2 vUv;
        varying vec3 vSphereNormal;

        void main() {
          float mask = texture2D(uLeafTex, vUv).r;
          if (mask < uAlphaThreshold) discard;

          float ndl = smoothstep(-0.15, 0.85, dot(normalize(vSphereNormal), normalize(uLightDirection)));
          vec3 baseCol = mix(uColorA, uColorB, ndl);
          vec3 shadowCol = uColorA * 0.72;
          vec3 finalCol = mix(shadowCol, baseCol, smoothstep(0.0, 0.45, ndl));

          gl_FragColor = vec4(finalCol, 1.0);
          #include <tonemapping_fragment>
          #include <colorspace_fragment>
        }
      `,
      side: THREE.DoubleSide,
    });
    if (isPurpleTree) {
      matCache.purpleMat = foliageMaterial;
    } else {
      matCache.greenMat = foliageMaterial;
    }
  } else {
    foliageMaterial.uniforms.uLeafTex.value = effectiveLeafMask;
  }

  if (!matCache.depthMat) {
    matCache.depthMat = new THREE.ShaderMaterial({
      uniforms: {
        uLeafTex: { value: effectiveLeafMask },
        uLeafScale: { value: 0.78 },
        uAlphaThreshold: { value: 0.42 },
      },
      vertexShader: /* glsl */ `
        attribute vec3 aLeafCenter;
        attribute vec3 aLeafLocalPos;
        attribute float aLeafPlaneSeed;
        uniform float uLeafScale;
        varying vec2 vUv;
        varying float vSeed;
        void main() {
          vUv = uv;
          vSeed = aLeafPlaneSeed;
          float angle = aLeafPlaneSeed * 6.2831853;
          float s = sin(angle);
          float c = cos(angle);
          vec3 scaledLocal = aLeafLocalPos * uLeafScale;
          float rotX = scaledLocal.x * c - scaledLocal.y * s;
          float rotY = scaledLocal.x * s + scaledLocal.y * c;

          mat4 mv = viewMatrix * modelMatrix * instanceMatrix;
          vec3 camRight = normalize(vec3(mv[0][0], mv[1][0], mv[2][0]));
          vec3 camUp = normalize(vec3(mv[0][1], mv[1][1], mv[2][1]));

          vec3 localPos = aLeafCenter + camRight * rotX + camUp * rotY;
          gl_Position = projectionMatrix * viewMatrix * modelMatrix * instanceMatrix * vec4(localPos, 1.0);
        }
      `,
      fragmentShader: /* glsl */ `
        uniform sampler2D uLeafTex;
        uniform float uAlphaThreshold;
        varying vec2 vUv;
        varying float vSeed;
        void main() {
          if (fract(vSeed * 19.0) > 0.62) discard;
          if (texture2D(uLeafTex, vUv).r < uAlphaThreshold) discard;
          gl_FragColor = vec4(vec3(1.0 - gl_FragCoord.z), 1.0);
        }
      `,
      side: THREE.DoubleSide,
    });
  } else {
    matCache.depthMat.uniforms.uLeafTex.value = effectiveLeafMask;
  }

  const markers =
    foliageMarkerMatrices.length > 0
      ? foliageMarkerMatrices
      : [new THREE.Matrix4().makeTranslation(0, 6.0, 0)];

  const foliageInstanced = new THREE.InstancedMesh(
    mergedClusterGeo,
    foliageMaterial,
    markers.length,
  );
  foliageInstanced.name = 'RealGlbTreeLeaves';
  foliageInstanced.frustumCulled = true;
  foliageInstanced.castShadow = true;
  foliageInstanced.receiveShadow = true;
  foliageInstanced.customDepthMaterial = matCache.depthMat;

  markers.forEach((m, idx) => {
    foliageInstanced.setMatrixAt(idx, m);
  });
  foliageInstanced.instanceMatrix.needsUpdate = true;
  trunkGroup.add(foliageInstanced);
}

interface St01TankTextureSet {
  fenderTex: THREE.CanvasTexture;
  turretSkirtTex: THREE.CanvasTexture;
  cannonShroudTex: THREE.CanvasTexture;
  goldCollarTex: THREE.CanvasTexture;
  frontGrilleTex: THREE.CanvasTexture;
  cyanGaugeTex: THREE.CanvasTexture;
  bellyPanTex: THREE.CanvasTexture;
  cockpitHazardSideTex: THREE.CanvasTexture;
  windshieldGlassTex: THREE.CanvasTexture;
}

const cachedSt01TankTextures = new Map<string, St01TankTextureSet>();

function getOrCreateSt01TankTextures(isSuper: boolean): St01TankTextureSet {
  const key = isSuper ? 'super' : 'standard';
  const existing = cachedSt01TankTextures.get(key);
  if (existing) return existing;

  const limeMain = isSuper ? '#38bdf8' : '#95cc39';
  const limeHighlight = isSuper ? '#7dd3fc' : '#b4e355';
  const limeShadow = isSuper ? '#0284c7' : '#6f9c24';
  const limeHatch = isSuper ? '#0369a1' : '#587f1a';

  // 1. Fender Armor Texture (3 segmented panels + top diagonal hatching lines + bottom bevel shadow)
  const fenderCanvas = document.createElement('canvas');
  fenderCanvas.width = 512;
  fenderCanvas.height = 256;
  const fCtx = fenderCanvas.getContext('2d')!;
  fCtx.fillStyle = limeMain;
  fCtx.fillRect(0, 0, 512, 256);
  // Top highlight band
  fCtx.fillStyle = limeHighlight;
  fCtx.fillRect(0, 0, 512, 54);
  // Bottom shadow band
  fCtx.fillStyle = limeShadow;
  fCtx.fillRect(0, 198, 512, 58);
  // 45-degree fine diagonal hatching along upper fender band (exact match to LEFT/RIGHT SIDE VIEW & green-screen render)
  fCtx.save();
  fCtx.beginPath();
  fCtx.rect(12, 16, 488, 62);
  fCtx.clip();
  fCtx.strokeStyle = limeHatch;
  fCtx.lineWidth = 4;
  for (let x = -120; x < 580; x += 14) {
    fCtx.beginPath();
    fCtx.moveTo(x, 12);
    fCtx.lineTo(x + 68, 82);
    fCtx.stroke();
  }
  fCtx.restore();
  // Vertical panel seam lines dividing the fender into 3 armored plates
  fCtx.strokeStyle = '#181e26';
  fCtx.lineWidth = 7;
  for (const sx of [164, 348]) {
    fCtx.beginPath();
    fCtx.moveTo(sx, 0);
    fCtx.lineTo(sx, 256);
    fCtx.stroke();
  }
  // Small amber-orange corner marker tab on front fender section
  fCtx.fillStyle = '#d97706';
  fCtx.fillRect(432, 92, 48, 22);
  fCtx.strokeStyle = '#181e26';
  fCtx.lineWidth = 6;
  fCtx.strokeRect(4, 4, 504, 248);
  const fenderTex = new THREE.CanvasTexture(fenderCanvas);
  fenderTex.colorSpace = THREE.SRGBColorSpace;
  fenderTex.needsUpdate = true;

  // 2. Turret Lower Gunmetal Skirt Texture (dark slate panel + recessed chamfer + orange "01" decal + 3 cyan slits)
  const skirtCanvas = document.createElement('canvas');
  skirtCanvas.width = 512;
  skirtCanvas.height = 256;
  const sCtx = skirtCanvas.getContext('2d')!;
  sCtx.fillStyle = '#262e3a';
  sCtx.fillRect(0, 0, 512, 256);
  // Inner recessed beveled trapezoid panel
  sCtx.fillStyle = '#1d242e';
  sCtx.strokeStyle = '#11161d';
  sCtx.lineWidth = 6;
  sCtx.beginPath();
  sCtx.moveTo(150, 28);
  sCtx.lineTo(476, 42);
  sCtx.lineTo(462, 224);
  sCtx.lineTo(168, 224);
  sCtx.closePath();
  sCtx.fill();
  sCtx.stroke();
  // Small orange-red tactical stripe decal at lower-front corner
  sCtx.fillStyle = '#c2410c';
  for (let i = 0; i < 3; i++) {
    sCtx.fillRect(410 + i * 14, 168, 9, 34);
  }
  // 3 Glowing Cyan Vertical Telemetry Slits on rear-side cheek
  for (let i = 0; i < 3; i++) {
    const cx = 42 + i * 28;
    const cy = 62 + i * 8;
    sCtx.fillStyle = '#083344';
    sCtx.fillRect(cx - 5, cy - 5, 18, 118);
    sCtx.fillStyle = '#22d3ee';
    sCtx.fillRect(cx, cy, 8, 108);
  }
  sCtx.strokeStyle = '#0f141b';
  sCtx.lineWidth = 7;
  sCtx.strokeRect(4, 4, 504, 248);
  const turretSkirtTex = new THREE.CanvasTexture(skirtCanvas);
  turretSkirtTex.colorSpace = THREE.SRGBColorSpace;
  turretSkirtTex.needsUpdate = true;

  // 3. Cannon Shroud Texture (lime-green heavy weapon pod + panel lines + wear marks)
  const shroudCanvas = document.createElement('canvas');
  shroudCanvas.width = 512;
  shroudCanvas.height = 256;
  const cCtx = shroudCanvas.getContext('2d')!;
  cCtx.fillStyle = limeMain;
  cCtx.fillRect(0, 0, 512, 256);
  cCtx.fillStyle = limeHighlight;
  cCtx.fillRect(0, 0, 512, 48);
  cCtx.fillStyle = limeShadow;
  cCtx.fillRect(0, 196, 512, 60);
  cCtx.strokeStyle = '#1b222c';
  cCtx.lineWidth = 6;
  cCtx.strokeRect(6, 6, 500, 244);
  cCtx.beginPath();
  cCtx.moveTo(132, 6);
  cCtx.lineTo(132, 250);
  cCtx.moveTo(132, 52);
  cCtx.lineTo(506, 52);
  cCtx.stroke();
  // Subtle battle scratch marks
  cCtx.strokeStyle = limeHatch;
  cCtx.lineWidth = 4;
  cCtx.beginPath();
  cCtx.moveTo(310, 140);
  cCtx.lineTo(355, 112);
  cCtx.moveTo(330, 152);
  cCtx.lineTo(368, 128);
  cCtx.stroke();
  const cannonShroudTex = new THREE.CanvasTexture(shroudCanvas);
  cannonShroudTex.colorSpace = THREE.SRGBColorSpace;
  cannonShroudTex.needsUpdate = true;

  // 4. Gold Octagonal Muzzle Collar Texture (warm gold rim with dark gunmetal recessed pockets)
  const collarCanvas = document.createElement('canvas');
  collarCanvas.width = 256;
  collarCanvas.height = 256;
  const gCtx = collarCanvas.getContext('2d')!;
  gCtx.fillStyle = '#e5b83b';
  gCtx.fillRect(0, 0, 256, 256);
  gCtx.fillStyle = '#fde047';
  gCtx.fillRect(0, 0, 256, 36);
  gCtx.fillStyle = '#b48618';
  gCtx.fillRect(0, 220, 256, 36);
  gCtx.fillStyle = '#272f3b';
  gCtx.strokeStyle = '#141820';
  gCtx.lineWidth = 6;
  gCtx.fillRect(28, 46, 200, 164);
  gCtx.strokeRect(28, 46, 200, 164);
  const goldCollarTex = new THREE.CanvasTexture(collarCanvas);
  goldCollarTex.colorSpace = THREE.SRGBColorSpace;
  goldCollarTex.needsUpdate = true;

  // 5. Front Hexagonal Grille Texture (3 glowing warm-amber horizontal radiator bars)
  const grilleCanvas = document.createElement('canvas');
  grilleCanvas.width = 256;
  grilleCanvas.height = 256;
  const grCtx = grilleCanvas.getContext('2d')!;
  grCtx.fillStyle = '#1b212a';
  grCtx.fillRect(0, 0, 256, 256);
  grCtx.strokeStyle = '#333d4d';
  grCtx.lineWidth = 12;
  grCtx.strokeRect(12, 12, 232, 232);
  for (let i = 0; i < 3; i++) {
    const y = 44 + i * 64;
    grCtx.fillStyle = '#0f1319';
    grCtx.fillRect(32, y - 8, 192, 42);
    const grad = grCtx.createLinearGradient(36, y, 36, y + 26);
    grad.addColorStop(0, '#fef08a');
    grad.addColorStop(0.5, '#f59e0b');
    grad.addColorStop(1, '#b45309');
    grCtx.fillStyle = grad;
    grCtx.fillRect(38, y, 180, 26);
  }
  const frontGrilleTex = new THREE.CanvasTexture(grilleCanvas);
  frontGrilleTex.colorSpace = THREE.SRGBColorSpace;
  frontGrilleTex.needsUpdate = true;

  // 6. Circular Cyan Pressure Gauge Texture (rear-left turret dial)
  const gaugeCanvas = document.createElement('canvas');
  gaugeCanvas.width = 128;
  gaugeCanvas.height = 128;
  const gaCtx = gaugeCanvas.getContext('2d')!;
  gaCtx.fillStyle = '#1b212a';
  gaCtx.fillRect(0, 0, 128, 128);
  gaCtx.beginPath();
  gaCtx.arc(64, 64, 54, 0, Math.PI * 2);
  gaCtx.fillStyle = '#0d9488';
  gaCtx.fill();
  gaCtx.lineWidth = 8;
  gaCtx.strokeStyle = '#11161d';
  gaCtx.stroke();
  gaCtx.beginPath();
  gaCtx.arc(64, 64, 40, 0, Math.PI * 2);
  gaCtx.fillStyle = '#5eead4';
  gaCtx.fill();
  // Gauge needle & center pin
  gaCtx.strokeStyle = '#11161d';
  gaCtx.lineWidth = 6;
  gaCtx.beginPath();
  gaCtx.moveTo(64, 64);
  gaCtx.lineTo(88, 42);
  gaCtx.stroke();
  const cyanGaugeTex = new THREE.CanvasTexture(gaugeCanvas);
  cyanGaugeTex.colorSpace = THREE.SRGBColorSpace;
  cyanGaugeTex.needsUpdate = true;

  // 7. Bottom Hull Belly Pan Texture (BOTTOM VIEW / TAMPAK BAWAH: 4 riveted grey armor plates + front louver grille)
  const bellyCanvas = document.createElement('canvas');
  bellyCanvas.width = 512;
  bellyCanvas.height = 512;
  const bCtx = bellyCanvas.getContext('2d')!;
  bCtx.fillStyle = '#252c37';
  bCtx.fillRect(0, 0, 512, 512);
  bCtx.strokeStyle = '#13171e';
  bCtx.lineWidth = 10;
  bCtx.strokeRect(16, 16, 480, 480);
  // 4 Vertical Armor Plates with corner rivets
  for (let i = 0; i < 4; i++) {
    const px = 44 + i * 88;
    bCtx.fillStyle = '#434c59';
    bCtx.fillRect(px, 56, 72, 400);
    bCtx.strokeStyle = '#171c24';
    bCtx.lineWidth = 5;
    bCtx.strokeRect(px, 56, 72, 400);
    bCtx.fillStyle = '#222832';
    for (const ry of [74, 438]) {
      for (const rx of [px + 14, px + 58]) {
        bCtx.beginPath();
        bCtx.arc(rx, ry, 5, 0, Math.PI * 2);
        bCtx.fill();
      }
    }
  }
  // Front Louvered Grille on Belly Pan
  bCtx.fillStyle = '#1a2029';
  bCtx.fillRect(402, 64, 68, 384);
  bCtx.fillStyle = '#323a46';
  for (let ly = 80; ly < 436; ly += 24) {
    bCtx.fillRect(412, ly, 48, 12);
  }
  const bellyPanTex = new THREE.CanvasTexture(bellyCanvas);
  bellyPanTex.colorSpace = THREE.SRGBColorSpace;
  bellyPanTex.needsUpdate = true;

  // 8. Cockpit Side Hazard Trim Texture (512x64 8:1 aspect ratio so 45° yellow/black stripes never stretch into horizontal lines)
  const hazardSideCanvas = document.createElement('canvas');
  hazardSideCanvas.width = 512;
  hazardSideCanvas.height = 64;
  const hsCtx = hazardSideCanvas.getContext('2d')!;
  hsCtx.fillStyle = '#eab308';
  hsCtx.fillRect(0, 0, 512, 64);
  hsCtx.fillStyle = '#181e26';
  for (let x = -64; x < 576; x += 64) {
    hsCtx.beginPath();
    hsCtx.moveTo(x, 0);
    hsCtx.lineTo(x + 32, 0);
    hsCtx.lineTo(x + 68, 64);
    hsCtx.lineTo(x + 36, 64);
    hsCtx.closePath();
    hsCtx.fill();
  }
  hsCtx.strokeStyle = '#11161d';
  hsCtx.lineWidth = 6;
  hsCtx.strokeRect(2, 2, 508, 60);
  const cockpitHazardSideTex = new THREE.CanvasTexture(hazardSideCanvas);
  cockpitHazardSideTex.colorSpace = THREE.SRGBColorSpace;
  cockpitHazardSideTex.needsUpdate = true;

  // 9. Curved Armored Windshield Glass Texture (translucent sky-cyan tint + diagonal white specular streaks)
  const wsCanvas = document.createElement('canvas');
  wsCanvas.width = 512;
  wsCanvas.height = 256;
  const wsCtx = wsCanvas.getContext('2d')!;
  const wsGrad = wsCtx.createLinearGradient(0, 0, 0, 256);
  wsGrad.addColorStop(0, 'rgba(186, 230, 253, 0.86)');
  wsGrad.addColorStop(0.35, 'rgba(103, 232, 249, 0.64)');
  wsGrad.addColorStop(1, 'rgba(34, 211, 238, 0.48)');
  wsCtx.fillStyle = wsGrad;
  wsCtx.fillRect(0, 0, 512, 256);

  // Diagonal white glass reflection streaks (matching green-screen reference 1:1)
  wsCtx.fillStyle = 'rgba(255, 255, 255, 0.58)';
  wsCtx.beginPath();
  wsCtx.moveTo(148, 24);
  wsCtx.lineTo(192, 24);
  wsCtx.lineTo(118, 232);
  wsCtx.lineTo(74, 232);
  wsCtx.closePath();
  wsCtx.fill();

  wsCtx.fillStyle = 'rgba(255, 255, 255, 0.36)';
  wsCtx.beginPath();
  wsCtx.moveTo(212, 24);
  wsCtx.lineTo(234, 24);
  wsCtx.lineTo(160, 232);
  wsCtx.lineTo(138, 232);
  wsCtx.closePath();
  wsCtx.fill();

  // Subtle inner cyan rim glow
  wsCtx.strokeStyle = 'rgba(224, 242, 254, 0.92)';
  wsCtx.lineWidth = 10;
  wsCtx.strokeRect(6, 6, 500, 244);

  const windshieldGlassTex = new THREE.CanvasTexture(wsCanvas);
  windshieldGlassTex.colorSpace = THREE.SRGBColorSpace;
  windshieldGlassTex.needsUpdate = true;

  const set: St01TankTextureSet = {
    fenderTex,
    turretSkirtTex,
    cannonShroudTex,
    goldCollarTex,
    frontGrilleTex,
    cyanGaugeTex,
    bellyPanTex,
    cockpitHazardSideTex,
    windshieldGlassTex,
  };
  cachedSt01TankTextures.set(key, set);
  return set;
}

