export type BlitzWeaponId =
  | 'unarmed'
  | 'pistol'
  | 'rifle'
  | 'bazooka'
  | 'laser'
  | 'gatling'
  | 'fishing_rod';

let cachedWeaponHazardTex: THREE.CanvasTexture | null = null;

function getWeaponHazardStripeTexture(): THREE.CanvasTexture {
  if (cachedWeaponHazardTex) return cachedWeaponHazardTex;
  const canvas = document.createElement('canvas');
  canvas.width = 128;
  canvas.height = 128;
  const ctx = canvas.getContext('2d')!;

  ctx.fillStyle = '#eab308';
  ctx.fillRect(0, 0, 128, 128);

  ctx.fillStyle = '#1c1f26';
  for (let i = -128; i < 256; i += 32) {
    ctx.beginPath();
    ctx.moveTo(i, 0);
    ctx.lineTo(i + 16, 0);
    ctx.lineTo(i + 16 + 128, 128);
    ctx.lineTo(i + 128, 128);
    ctx.closePath();
    ctx.fill();
  }

  ctx.strokeStyle = '#14161c';
  ctx.lineWidth = 6;
  ctx.strokeRect(0, 0, 128, 128);

  const tex = new THREE.CanvasTexture(canvas);
  tex.colorSpace = THREE.SRGBColorSpace;
  tex.wrapS = THREE.RepeatWrapping;
  tex.wrapT = THREE.RepeatWrapping;
  tex.needsUpdate = true;
  cachedWeaponHazardTex = tex;
  return tex;
}

