        const x = col * 128 + offset;
        ctx.fillStyle = stoneTones[(row + col + 4) % stoneTones.length];
        ctx.fillRect(x, y, 126, courseH - 3);
        ctx.fillStyle = 'rgba(255,255,255,0.08)';
