function getLv3AshlarStonePlinthTexture(): THREE.CanvasTexture {
  const key = 'lv3_ashlar_stone_plinth';
  const cached = milTexCache.get(key);
  if (cached) return cached;

  const canvas = document.createElement('canvas');
  canvas.width = 512;
  canvas.height = 256;
  const ctx = canvas.getContext('2d');
  if (ctx) {
    ctx.fillStyle = '#383b42';
    ctx.fillRect(0, 0, 512, 256);

    // Polygonal & random-ashlar Japanese castle-style basalt stone plinth blocks
    const stonePalette = ['#5e626b', '#52565f', '#686c75', '#4b4f58', '#585c65', '#636770'];
    const rows = [
      { y: 4, h: 58, widths: [94, 72, 110, 84, 66, 86] },
      { y: 66, h: 62, widths: [68, 104, 78, 96, 88, 78] },
      { y: 132, h: 56, widths: [108, 76, 92, 68, 94, 74] },
      { y: 192, h: 60, widths: [80, 88, 102, 74, 86, 82] },
    ];
    rows.forEach((row, rIdx) => {
      let curX = 4;
      row.widths.forEach((w, cIdx) => {
        const bw = Math.min(w - 5, 508 - curX);
        if (bw <= 8) return;
        ctx.fillStyle = stonePalette[(rIdx * 3 + cIdx) % stonePalette.length];
        ctx.fillRect(curX, row.y, bw, row.h);
        // Subtle bevel highlight on top/left of each dressed stone block
        ctx.fillStyle = 'rgba(255,255,255,0.11)';
        ctx.fillRect(curX + 2, row.y + 2, bw - 4, 4);
        ctx.fillRect(curX + 2, row.y + 2, 4, row.h - 4);
        // Shadowed bottom/right edge
        ctx.fillStyle = 'rgba(18,20,26,0.38)';
        ctx.fillRect(curX + 2, row.y + row.h - 5, bw - 2, 4);
        curX += w;
      });
    });
  }
  const tex = new THREE.CanvasTexture(canvas);
  tex.colorSpace = THREE.SRGBColorSpace;
  milTexCache.set(key, tex);
  return tex;
}

