  addHqBonsaiShrubCluster(hangarGroup, -3.48, -3.56, -1);

  // Rising 3D Smoke Plumes from the Rear Exhaust Ventilation Stack
  if (!sharedChimneyPuffGeo) {
    sharedChimneyPuffGeo = new THREE.IcosahedronGeometry(0.32, 2);
  }
  const hangarSmokePuffs: ChimneySmokePuff[] = [];
  const hangarSmokeContainer = new THREE.Group();
  hangarSmokeContainer.name = 'HangarRoofChimneySmoke';
  hangarGroup.add(hangarSmokeContainer);

  const emitterOrigin = new THREE.Vector3(-3.48, 6.62, 0.18);
  const puffsCount = 8;
  for (let pIdx = 0; pIdx < puffsCount; pIdx++) {
    const colorHex = CHIMNEY_SMOKE_PALETTE[pIdx % CHIMNEY_SMOKE_PALETTE.length];
    const puffGrp = new THREE.Group();
    puffGrp.frustumCulled = false;

    const puffMesh = new THREE.Mesh(
      sharedChimneyPuffGeo,
      new THREE.MeshStandardMaterial({ color: colorHex, roughness: 0.95 }),
    );
    puffMesh.frustumCulled = false;
    upgradeMeshToBlitzWorldMaterial(puffMesh, windUniforms, colorHex);
    const puffStroke = createBlitzStrokeMesh(sharedChimneyPuffGeo, 0.015);
    if (puffStroke) {
      puffStroke.frustumCulled = false;
      puffMesh.add(puffStroke);
    }
    puffGrp.add(puffMesh);

    const subLobe = new THREE.Mesh(
      sharedChimneyPuffGeo,
      new THREE.MeshStandardMaterial({ color: colorHex, roughness: 0.95 }),
    );
    subLobe.scale.set(0.68, 0.62, 0.68);
    subLobe.position.set(0.20, 0.08, -0.14);
    subLobe.frustumCulled = false;
    upgradeMeshToBlitzWorldMaterial(subLobe, windUniforms, colorHex);
    puffGrp.add(subLobe);

    hangarSmokeContainer.add(puffGrp);
    const puffData: ChimneySmokePuff = {
      group: puffGrp,
      puffMesh,
      emitterOrigin,
      phaseOffset: pIdx / puffsCount,
      lifetime: 2.2 + (pIdx % 3) * 0.25,
      upwardSpeed: 1.55 + (pIdx % 3) * 0.22,
      driftX: 0.82 + ((pIdx % 3) - 1) * 0.14,
      driftZ: -0.52 + ((pIdx % 3) - 1) * 0.12,
      swayAmp: 0.22 + (pIdx % 2) * 0.06,
      swayFreq: 1.4 + (pIdx % 3) * 0.2,
      swayPhase: pIdx * 1.15,
      startScale: 0.24 + (pIdx % 2) * 0.05,
      endScale: 0.64 + (pIdx % 3) * 0.10,
      spinSpeed: (pIdx % 2 === 0 ? 1 : -1) * 0.5,
    };
    updateSingleChimneySmokePuff(puffData, 2.2);
    hangarSmokePuffs.push(puffData);
  }


