  addBasePart(checkpointGroup, new THREE.BoxGeometry(0.54, 1.45, 0.54), COL_CONCRETE, [1.85, 0.72, 1.75], [0, 0, 0], [1, 1, 1], 0.015);
  addBasePart(checkpointGroup, new THREE.BoxGeometry(0.44, 0.52, 0.44), COL_STEEL_LIGHT, [1.85, 1.18, 1.79], [0, 0, 0], [1, 1, 1], 0.012);
