  addBasePart(checkpointGroup, new THREE.BoxGeometry(0.32, 2.75, 0.32), COL_CONCRETE, [0, 1.38, -5.85], [0, 0, 0], [1, 1, 1], 0.016);
  addBasePart(checkpointGroup, new THREE.BoxGeometry(0.14, 2.30, 0.62), '#ffffff', [0, 1.24, -5.52], [0, 0, 0], [1, 1, 1], 0.014, camoNetTex);
